-- Master Clean Migration for 5 Mine JSON Courses (269 Questions Total)
-- Pure standard SQL - No DO 18450 blocks to prevent any SQL parser syntax errors!

-- 1. Ensure schema columns exist
ALTER TABLE public.questions
  ADD COLUMN IF NOT EXISTS correct_option_count INT NOT NULL DEFAULT 1,
  ADD COLUMN IF NOT EXISTS total_options INT NOT NULL DEFAULT 4,
  ADD COLUMN IF NOT EXISTS question_type TEXT DEFAULT 'mcq';

-- 2. Clean wipe for these 5 courses to prevent duplicates
DELETE FROM public.questions 
WHERE subtopic_id IN (
  SELECT s.id FROM public.subtopics s
  JOIN public.courses c ON s.course_id = c.id
  WHERE c.name IN (
    'Oracle APEX Developer Professional',
    'Oracle AI Agent Studio for Fusion Applications Developers',
    'XML',
    'Oracle AI Vector Search',
    'OCI Data Science Professional'
  )
);

DELETE FROM public.subtopics 
WHERE course_id IN (
  SELECT id FROM public.courses WHERE name IN (
    'Oracle APEX Developer Professional',
    'Oracle AI Agent Studio for Fusion Applications Developers',
    'XML',
    'Oracle AI Vector Search',
    'OCI Data Science Professional'
  )
);

DELETE FROM public.courses WHERE name IN (
  'Oracle APEX Developer Professional',
  'Oracle AI Agent Studio for Fusion Applications Developers',
  'XML',
  'Oracle AI Vector Search',
  'OCI Data Science Professional'
);

