INSERT INTO public.courses (id, name, description, icon) VALUES ('66df60aa-131f-5fac-b396-6891ae478e4d', 'Oracle APEX Developer Professional', 'Master enterprise APEX application development, interactive reports, workflows, authentication, OCI AI services integration, and AI Vector Search RAG solutions.', 'layers');
INSERT INTO public.subtopics (id, course_id, name, order_index) VALUES ('4118f95a-d3fc-5e3c-91e7-f7049b8378b3', '66df60aa-131f-5fac-b396-6891ae478e4d', 'APEX Workspace & App Fundamentals', 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('c5fcf478-b03d-5d32-bda2-7cf2050cd20b', '4118f95a-d3fc-5e3c-91e7-f7049b8378b3', 'mcq'::public.question_type, 'mcq', 'You can create an APEX workspace and build APEX apps on which of the following platforms?', '["Oracle Autonomous Cloud", "Oracle XE", "Amazon RDS", "Microsoft Azure", "All of the above"]'::jsonb, '[4]'::jsonb, 'Oracle APEX is database-centric and runs wherever Oracle Database runs — including Oracle Autonomous Cloud (ADB/ATP/ADW), Oracle Database XE (Express Edition) on-premises, Amazon RDS for Oracle, and Microsoft Azure (Oracle Database@Azure).
Key Takeaway: APEX is fully portable across on-premises, OCI, AWS RDS, and Azure wherever Oracle DB is supported.', 'Correct'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('fd967661-a159-5bd6-b011-fa827c50caba', '4118f95a-d3fc-5e3c-91e7-f7049b8378b3', 'msq'::public.question_type, 'msq', 'Which three are the main components of APEX workspace homepage?', '["RESTful Services", "SQL Workshop", "App Builder", "Gallery"]'::jsonb, '[1, 2, 3]'::jsonb, 'Technical Rationale: The correct choices are: SQL Workshop, App Builder, Gallery. These options collectively satisfy all criteria described in the question. The remaining distractors (RESTful Services) represent invalid configurations or misconceptions.
Key Takeaway: Carefully verify each required feature when evaluating multi-answer (MSQ) questions.', 'Correct'::public.difficulty_level, medium, 3);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('3beb1a51-710e-5d88-8212-b4b0b12d74d0', '4118f95a-d3fc-5e3c-91e7-f7049b8378b3', 'msq'::public.question_type, 'msq', 'Which two are true about Oracle APEX?', '["Requires no additional client software. A web browser is the app development IDE.", "Performs the data processing in a middle-tier server", "Requires developers to be proficient in Java, Python and other programming languages.", "Is declarative. It requires no code generation."]'::jsonb, '[0, 3]'::jsonb, 'Technical Rationale: The correct choices are: Requires no additional client software. A web browser is the app development IDE., Is declarative. It requires no code generation.. These options collectively satisfy all criteria described in the question. The remaining distractors (Performs the data processing in a middle-tier server, Requires developers to be proficient in Java, Python and other programming languages.) represent invalid configurations or misconceptions.
Key Takeaway: Carefully verify each required feature when evaluating multi-answer (MSQ) questions.', 'Correct'::public.difficulty_level, medium, 2);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('0b640b4b-fb7b-56f7-bf51-4e0f219ab1ab', '4118f95a-d3fc-5e3c-91e7-f7049b8378b3', 'msq'::public.question_type, 'msq', 'Which two among the following are TRUE about Low Code Apps?', '["Provide Rich Functionality with Less Code", "Expensive", "Scalable", "Not Mobile Friendly"]'::jsonb, '[0, 2]'::jsonb, 'Oracle APEX Low-Code Architecture:
• Declarative development enables rich, responsive, enterprise-grade functionality with minimal custom coding.
• It is highly scalable because data processing occurs directly inside the Oracle Database engine with zero middle-tier latency.
Correct options: Provide Rich Functionality with Less Code, Scalable.
Key Takeaway: Low-code apps provide high productivity and enterprise scalability without requiring multi-tier overhead.', 'Correct'::public.difficulty_level, medium, 2);
INSERT INTO public.subtopics (id, course_id, name, order_index) VALUES ('80c630cf-093f-5c83-9eed-2171ed0d269f', '66df60aa-131f-5fac-b396-6891ae478e4d', 'SQL Workshop & Quick SQL Shorthand', 2);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('df85b835-7aa0-50bf-a4d5-932300de20a9', '80c630cf-093f-5c83-9eed-2171ed0d269f', 'msq'::public.question_type, 'msq', 'From SQL Workshop, you can perform which two of the following actions?', '["Delete database", "Create an APEX user", "Run SQL commands and scripts", "Create and view database objects"]'::jsonb, '[2, 3]'::jsonb, 'SQL Workshop provides a full browser-based IDE to manage database objects, execute ad-hoc SQL commands, run PL/SQL scripts, and view table schemas.
Correct options: Run SQL commands and scripts, Create and view database objects.
Key Takeaway: SQL Workshop is the database developer hub inside Oracle APEX.', 'Correct'::public.difficulty_level, medium, 2);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('491d20b2-a4ba-53db-a483-fa59af881319', '80c630cf-093f-5c83-9eed-2171ed0d269f', 'msq'::public.question_type, 'msq', 'Using Data Workshop, you can perform which three tasks:', '["Load data using various file formats such as XLSX, CSV, XML, and JSON", "Delete data from the database", "Export vast amount of data from the database into a file", "Load vast amount of data into the database"]'::jsonb, '[0, 2, 3]'::jsonb, 'Data Workshop in APEX allows you to:
1. Load data from various formats including XLSX (Excel), CSV, XML, and JSON into new or existing tables.
2. Export data from tables into flat files (CSV, XML, JSON, XLSX).
3. Load massive datasets with automatic column mapping and validation.
Correct options: Load data using various file formats such as XLSX, CSV, XML, and JSON, Export vast amount of data from the database into a file, Load vast amount of data into the database.
Key Takeaway: Data Workshop handles bidirectional ETL (loading and exporting) across structured formats.', 'Correct'::public.difficulty_level, medium, 3);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('007d7e94-7a08-5e02-a7fc-197b7cfb8710', '80c630cf-093f-5c83-9eed-2171ed0d269f', 'mcq'::public.question_type, 'mcq', 'Which component in SQL Workshop allows you to build queries graphically without manual SQL coding?', '["Query Builder", "Quick SQL", "SQL commands", "Data Workshop"]'::jsonb, '[0]'::jsonb, 'SQL Workshop provides a full browser-based IDE to manage database objects, execute ad-hoc SQL commands, run PL/SQL scripts, and view table schemas.
Correct options: Query Builder.
Key Takeaway: SQL Workshop is the database developer hub inside Oracle APEX.', 'Correct!'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('0a5240cf-09ce-5211-9107-4c7d64e542dc', '80c630cf-093f-5c83-9eed-2171ed0d269f', 'msq'::public.question_type, 'msq', 'What three are the result of the following QuickSQL shorthand notation do?departments /insert 4
  name /nn
  location
  country', '["Inserts 4 rows of random data into the departments table", "Creates an id column as a primary key", "Create the departments table with 3 columns", "Create the departments table with 4 columns"]'::jsonb, '[0, 1, 3]'::jsonb, 'QuickSQL shorthand syntax rules:
• ''departments'': Generates table DEPARTMENTS with an automatic primary key ID column (IDENTITY).
• ''/insert 4'': Generates INSERT statements for 4 sample data rows.
• ''name /nn'': Creates VARCHAR2 column NAME with a NOT NULL constraint.
• ''location'' & ''country'': Creates VARCHAR2 columns LOCATION and COUNTRY.
Therefore, the table has 4 columns (ID, NAME, LOCATION, COUNTRY), inserts 4 rows of sample data, and creates an ID primary key.
Key Takeaway: QuickSQL automatically generates an ID primary key by default unless overridden.', 'Correct!'::public.difficulty_level, medium, 3);
INSERT INTO public.subtopics (id, course_id, name, order_index) VALUES ('69d820b5-5c02-52d5-841c-503733dd4a67', '66df60aa-131f-5fac-b396-6891ae478e4d', 'Friendly URLs & Universal Theme Setup', 3);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('9ff09b52-9445-5667-a313-f6e89fc4482c', '69d820b5-5c02-52d5-841c-503733dd4a67', 'msq'::public.question_type, 'msq', 'Choose the three correct options in the given friendly URL syntax: https://example.com:5500/ords/r/mycompany/hr-app/update-employees?session=13766599855150', '["mycompany is the path-prefix which is by default the workspace name", "13766599855150 is the session ID. A new ID is generated for each session.", "update-employees is the PL/SQL procedure to update the employee details.", "hr-app is the application alias."]'::jsonb, '[0, 1, 3]'::jsonb, 'Technical Rationale: The correct choices are: mycompany is the path-prefix which is by default the workspace name, 13766599855150 is the session ID. A new ID is generated for each session., hr-app is the application alias.. These options collectively satisfy all criteria described in the question. The remaining distractors (update-employees is the PL/SQL procedure to update the employee details.) represent invalid configurations or misconceptions.
Key Takeaway: Carefully verify each required feature when evaluating multi-answer (MSQ) questions.', 'Correct'::public.difficulty_level, medium, 3);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('98e03f96-6dd3-57b0-bf07-b7b7f5d8565f', '69d820b5-5c02-52d5-841c-503733dd4a67', 'msq'::public.question_type, 'msq', 'Choose the two statements that are TRUE about the Universal Theme in APEX.', '["Easy customization", "Responsive UI", "Not designed to work on tablets", "The developers must have extensive knowledge about Javascript, CSS and HTML in order to use the Universal Theme."]'::jsonb, '[0, 1]'::jsonb, 'Universal Theme (Theme 42) in Oracle APEX provides:
1. Responsive Web Design: Adapts smoothly to mobile, tablet, and desktop viewports.
2. Accessible UI components: Meets WCAG 2.1 AA accessibility guidelines.
3. Deep declarative integration: Supports Theme Roller for live customization without CSS knowledge.
Correct options: Easy customization, Responsive UI.
Key Takeaway: Universal Theme is responsive, accessible, and declaratively customizable via Theme Roller.', 'Correct'::public.difficulty_level, medium, 2);
