INSERT INTO public.subtopics (id, course_id, name, order_index) VALUES ('9de0b789-1787-5b96-a373-a4a265607ffe', '66df60aa-131f-5fac-b396-6891ae478e4d', 'Page Designer & Dialog Modes', 4);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('c0896d95-b29c-5e2b-b13c-bfb472b283f5', '9de0b789-1787-5b96-a373-a4a265607ffe', 'msq'::public.question_type, 'msq', 'The Page Designer Toolbar allows you to perform which two of the following actions?', '["Create a new page", "Export the application", "Navigate to Shared Components", "Delete the application"]'::jsonb, '[0, 2]'::jsonb, 'AI Agent Studio Tool Calling:
• Tools allow LLM agents to interact with external systems (Fusion REST APIs, ERP/HCM databases, vector stores, third-party webhooks).
• The agent decides dynamically when and which tool to invoke based on user intent and tool schema descriptions.
Correct choice: Create a new page, Navigate to Shared Components.
Key Takeaway: Tools provide agents with actionable agency to execute real-time business actions in Fusion Apps.', 'Correct'::public.difficulty_level, medium, 2);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('7087d21e-a476-5607-8fb3-85294976803d', '9de0b789-1787-5b96-a373-a4a265607ffe', 'mcq'::public.question_type, 'mcq', 'When a button is pressed, an overlay window is positioned within the viewport. What kind of page mode is it?', '["Non-Modal Dialog", "Help Page", "Normal Page", "Modal Dialog"]'::jsonb, '[3]'::jsonb, 'Technical Rationale: The correct answer is ''Modal Dialog''. In this scenario, ''Modal Dialog'' satisfies the architectural and operational requirements. Incorrect options (Non-Modal Dialog, Help Page) do not provide this exact capability.
Key Takeaway: Remember ''Modal Dialog'' as the standard exam pattern for this topic.', 'Correct'::public.difficulty_level, medium, 1);
