INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('38d413c0-b702-5732-87ca-e8d3da0dd5d5', '025a816a-ad4b-52c6-865c-658ee3fea118', 'mcq'::public.question_type, 'mcq', 'In a Classic Report, an end user can perform which one of the following actions?', '["Sort the columns of the report.", "Filter values of a column in the report.", "Rearrange the columns in the report.", "Create Control Breaks in the report."]'::jsonb, '[0]'::jsonb, 'Technical Rationale: The correct answer is ''Sort the columns of the report.''. In this scenario, ''Sort the columns of the report.'' satisfies the architectural and operational requirements. Incorrect options (Filter values of a column in the report., Rearrange the columns in the report.) do not provide this exact capability.
