INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('21d6e89c-fe7a-5bae-bf13-4181379c67da', '025a816a-ad4b-52c6-865c-658ee3fea118', 'msq'::public.question_type, 'msq', 'Which two of the following capabilities are TRUE for both Interactive Report and Interactive Grid?', '["End user can rearrange the report interactively using the mouse.", "End user can save the report", "End user can customize how and what data is displayed.", "End user can add, modify, and refresh data directly on the report."]'::jsonb, '[1, 2]'::jsonb, 'Interactive Reports (IR) vs Interactive Grids (IG):
• Interactive Reports: Read-only powerful reporting tool with end-user filtering, aggregation, highlighting, and charting.
• Interactive Grids: Rich data presentation component supporting both read-only and editable multi-row grid capabilities.
Correct options: End user can save the report, End user can customize how and what data is displayed..
Key Takeaway: Interactive Grid supports rich inline row editing; Interactive Report is strictly read-only analytical reporting.', 'Correct'::public.difficulty_level, medium, 2);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
