INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('b4707297-5340-5ca9-897c-71427c6f68a8', '2de96ec8-6548-5bfb-a27c-59b56fae4e2d', 'msq'::public.question_type, 'msq', 'Choose the two statements that are TRUE about an Interactive Report. As a developer:', '["You can customize the Actions menu to include or exclude certain options.", "You can modify the data in the report after running the app", "You can customize the pagination", "You cannot modify the report source query"]'::jsonb, '[0, 2]'::jsonb, 'Interactive Reports (IR) vs Interactive Grids (IG):
• Interactive Reports: Read-only powerful reporting tool with end-user filtering, aggregation, highlighting, and charting.
