INSERT INTO public.subtopics (id, course_id, name, order_index) VALUES ('26046950-3020-554b-8628-9bf440a42528', '66df60aa-131f-5fac-b396-6891ae478e4d', 'Universal Theme Customizations & Styles', 14);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('f2d40db5-bfef-5198-9c98-f12b4f2d4d59', '26046950-3020-554b-8628-9bf440a42528', 'msq'::public.question_type, 'msq', 'What are the three key features of Universal Theme?', '["Support for single theme", "Easy Customization", "Responsive Design", "Versatile UI Components"]'::jsonb, '[1, 2, 3]'::jsonb, 'Universal Theme (Theme 42) in Oracle APEX provides:
1. Responsive Web Design: Adapts smoothly to mobile, tablet, and desktop viewports.
2. Accessible UI components: Meets WCAG 2.1 AA accessibility guidelines.
3. Deep declarative integration: Supports Theme Roller for live customization without CSS knowledge.
Correct options: Easy Customization, Responsive Design, Versatile UI Components.
Key Takeaway: Universal Theme is responsive, accessible, and declaratively customizable via Theme Roller.', 'Correct'::public.difficulty_level, medium, 3);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('c00e0faa-a3f1-5cd9-ae9c-d710a969953a', '26046950-3020-554b-8628-9bf440a42528', 'mcq'::public.question_type, 'mcq', 'Which of the following options in the Developer Toolbar enables you to customize the look and feel of the application?', '["Customize", "Debug", "Session", "Quick Edit"]'::jsonb, '[0]'::jsonb, 'AI Agent Studio Tool Calling:
• Tools allow LLM agents to interact with external systems (Fusion REST APIs, ERP/HCM databases, vector stores, third-party webhooks).
• The agent decides dynamically when and which tool to invoke based on user intent and tool schema descriptions.
Correct choice: Customize.
Key Takeaway: Tools provide agents with actionable agency to execute real-time business actions in Fusion Apps.', 'Correct'::public.difficulty_level, medium, 1);
