-- ========================================================
-- Course: Oracle AI Vector Search
-- ========================================================
INSERT INTO public.courses (id, name, description, icon) VALUES ('49eb4e03-fb89-51e7-96b8-960445d5a997', 'Oracle AI Vector Search', 'Understand and implement vector data types in Oracle Database 23ai, vector embeddings, similarity search, HNSW & IVF indexes, and PL/SQL RAG apps.', 'cpu');
INSERT INTO public.subtopics (id, course_id, name, order_index) VALUES ('ec77b5db-100d-572a-bc4f-60be51c527ff', '49eb4e03-fb89-51e7-96b8-960445d5a997', 'Vector Data Types & Embeddings Fundamentals', 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('73978a43-4f77-51db-beeb-41074f063c0f', 'ec77b5db-100d-572a-bc4f-60be51c527ff', 'mcq'::public.question_type, 'mcq', 'Where can vector embeddings be generated in Oracle Database 23ai?', '["Only within the database ", "Both outside and within the database", "Only outside the database ", "Nowhere, vector embeddings are not generated"]'::jsonb, '[1]'::jsonb, 'Oracle AI Vector Search natively integrates dense vector embeddings with relational tables, enabling hybrid searches combining SQL filters (WHERE clause) with semantic similarity. The correct choice is: Both outside and within the database.
Key Takeaway: Oracle 23ai runs vector similarity directly inside the database kernel alongside relational data.', 'Your answer is Correct.Explanation:  Vector embeddings can be generated "Outside the DB" and "Within the DB." Oracle Database 23ai offers flexibility in terms of where these embeddings can be created. Users can choose to generate embeddings using external tools or services and then import them into the database. Alternatively, they can leverage the capabilities of Oracle Database 23ai itself to generate embeddings directly within the database environment.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('02acb260-452b-5be3-9175-6e8cb6189aff', 'ec77b5db-100d-572a-bc4f-60be51c527ff', 'mcq'::public.question_type, 'mcq', 'What is the main advantage of creating Vector Indexes in Oracle Database 23ai?', '["They compress the vector data, reducing storage space. ", "They enable efficient searching for similar vectors in large vector spaces.", "They convert relational data into vector representations.", "They allow for direct comparison of vectors using operators like = or <. "]'::jsonb, '[1]'::jsonb, 'Vector Index Types in Oracle AI Vector Search:
1. HNSW (Hierarchical Navigable Small World): Graph-based in-memory index providing high recall and fast approximate nearest neighbor (ANN) search with higher build time.
2. IVF (Inverted File Flat): Partition-based inverted list clustering index with lower memory footprint.
Correct answer: They enable efficient searching for similar vectors in large vector spaces..
Key Takeaway: HNSW optimizes for query latency and recall; IVF optimizes for memory efficiency.', 'Your answer is Correct.Explanation:  They enable efficient searching for similar vectors in large vector spaces.Explanation: Vector Indexes can optimize vector search operations. These indexes are specifically designed to handle the challenges of searching for similar vectors within potentially vast vector spaces. They employ various techniques to speed up the search process, making it feasible to find relevant vectors efficiently even when dealing with massive amounts of data.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('191fbeb3-b6cf-5959-a8a6-2cf30c86915b', 'ec77b5db-100d-572a-bc4f-60be51c527ff', 'mcq'::public.question_type, 'mcq', 'How are vector embeddings stored in Oracle Database 23ai?', '["They are not stored; they are only used for querying.", "They are appended as metadata to existing data files. ", "They are stored in a separate, specialized vector database. ", "By creating columns with the VECTOR data type in relational tables. "]'::jsonb, '[3]'::jsonb, 'Oracle AI Vector Search natively integrates dense vector embeddings with relational tables, enabling hybrid searches combining SQL filters (WHERE clause) with semantic similarity. The correct choice is: By creating columns with the VECTOR data type in relational tables. .
Key Takeaway: Oracle 23ai runs vector similarity directly inside the database kernel alongside relational data.', 'Your answer is Correct.Explanation:  Embeddings are stored by creating columns with the data type VECTOR within the relational tables of the database. This approach integrates vector data seamlessly into the existing relational database structure, allowing for efficient management and querying alongside other business data.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('d048ed65-8a2c-5560-8551-21c4249f24ff', 'ec77b5db-100d-572a-bc4f-60be51c527ff', 'mcq'::public.question_type, 'mcq', 'What types of searches can be combined when querying data in Oracle Database 23ai that includes vector embeddings?', '["Keyword searches and sentiment analysis. ", "Geospatial searches and time-series analysis. ", "Similarity searches and relational searches.", "Image recognition searches and natural language processing."]'::jsonb, '[2]'::jsonb, 'Oracle AI Vector Search natively integrates dense vector embeddings with relational tables, enabling hybrid searches combining SQL filters (WHERE clause) with semantic similarity. The correct choice is: Similarity searches and relational searches..
Key Takeaway: Oracle 23ai runs vector similarity directly inside the database kernel alongside relational data.', 'Your answer is Correct.Explanation:  Oracle Database 23ai allows for the combination of "Similarity searches" and "Relational searches." This powerful capability enables users to perform complex queries that leverage both the semantic relationships captured in vector embeddings (similarity searches) and the structured information stored in relational tables (relational searches). This combined approach offers greater flexibility and precision in retrieving relevant data.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('1287dc66-1730-597d-bf48-f1412d3c57ba', 'ec77b5db-100d-572a-bc4f-60be51c527ff', 'mcq'::public.question_type, 'mcq', 'What is the first step in the Oracle AI Vector Search Workflow?', '["Generate Vector Embeddings ", "Vector Indexes", "Store Vector Embeddings ", "Query Data with Similarity Searches "]'::jsonb, '[0]'::jsonb, 'Oracle AI Vector Search natively integrates dense vector embeddings with relational tables, enabling hybrid searches combining SQL filters (WHERE clause) with semantic similarity. The correct choice is: Generate Vector Embeddings .
Key Takeaway: Oracle 23ai runs vector similarity directly inside the database kernel alongside relational data.', 'Your answer is Correct.Explanation:  The initial step in the Oracle AI Vector Search workflow is to "Generate Vector Embeddings." Vector embeddings are mathematical representations of data points (like text, images, or other unstructured content) in a multi-dimensional vector space. Generating these embeddings is the foundation for enabling similarity searches within the Oracle Database environment.'::public.difficulty_level, medium, 1);
INSERT INTO public.subtopics (id, course_id, name, order_index) VALUES ('e707974d-a436-58cc-ab4c-74638509a8ad', '49eb4e03-fb89-51e7-96b8-960445d5a997', 'SQL Insertion & Vector Embeddings Storage', 2);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('d7ace120-551a-5dfc-b4a3-fe033d3b4614', 'e707974d-a436-58cc-ab4c-74638509a8ad', 'mcq'::public.question_type, 'mcq', 'Which of the following SQL statements correctly inserts a vector into a table named product_embeddings with a column named embedding of the VECTOR data type?', '["INSERT INTO product_embeddings VALUES ( \"[0.1, 0.2, 0.3]\")", "INSERT INTO product_embeddings VALUES ( (0.1, 0.2, 0.3))", "INSERT INTO product_embeddings VALUES ( ''[0.1, 0.2, 0.3]'')", "INSERT INTO product_embeddings VALUES ( VECTOR (0.1, 0.2, 0.3)) "]'::jsonb, '[2]'::jsonb, 'Oracle AI Vector Search natively integrates dense vector embeddings with relational tables, enabling hybrid searches combining SQL filters (WHERE clause) with semantic similarity. The correct choice is: INSERT INTO product_embeddings VALUES ( ''[0.1, 0.2, 0.3]'').
Key Takeaway: Oracle 23ai runs vector similarity directly inside the database kernel alongside relational data.', 'Your answer is Correct.Explanation:  Based on standard SQL syntax, option "INSERT INTO product_embeddings VALUES ( ''[0.1, 0.2, 0.3]'')" is the correct way to insert a vector.

You need to separate each number with a comma.
You need to enclose the array with single quotes.

The other options use incorrect syntax for vector creation or insertion.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('9a2884e7-fd93-5d67-9d53-f49039969366', 'e707974d-a436-58cc-ab4c-74638509a8ad', 'mcq'::public.question_type, 'mcq', 'What type of data, can be used for creating Vector Embeddings?', '["Image data ", "Audio data ", "Text data ", "All of the above"]'::jsonb, '[3]'::jsonb, 'Oracle AI Vector Search natively integrates dense vector embeddings with relational tables, enabling hybrid searches combining SQL filters (WHERE clause) with semantic similarity. The correct choice is: All of the above.
Key Takeaway: Oracle 23ai runs vector similarity directly inside the database kernel alongside relational data.', 'Your answer is Correct.Explanation:  A vector embedding is a numerical representation of text, image, audio, or video data that encodes the semantic content of the data.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('adf8f9f5-8037-55c6-8ef0-d725e1142c37', 'e707974d-a436-58cc-ab4c-74638509a8ad', 'mcq'::public.question_type, 'mcq', 'Which of the following mathematical operations can be directly performed between two vectors (v1 and v2) using built-in functions or operators in Oracle Database 23ai?', '["Addition (v1 + v2) ", "Subtraction (v1 - v2) ", "Multiplication (v1 - v2) ", "None of these"]'::jsonb, '[3]'::jsonb, 'Oracle AI Vector Search natively integrates dense vector embeddings with relational tables, enabling hybrid searches combining SQL filters (WHERE clause) with semantic similarity. The correct choice is: None of these.
Key Takeaway: Oracle 23ai runs vector similarity directly inside the database kernel alongside relational data.', 'Your answer is Correct.Explanation:  Vectors are an array of numbers and performing arithmetic operations like addition, subtraction, multiplication, or division between vectors using built-in functions or operators is not supported.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('4a1cbb65-6318-5d7e-a29f-15871078648f', 'e707974d-a436-58cc-ab4c-74638509a8ad', 'mcq'::public.question_type, 'mcq', 'Considering the limitations of comparison operations between vectors, which approach would be suitable for finding vectors similar to a query vector q in a table named items with a vector column named embedding?', '["Use specialized functions or libraries that calculate vector distances or similarities. ", "Convert the vectors to string representations and compare them using string matching functions.", "SELECT * FROM items WHERE embedding = q ", "SELECT * FROM items WHERE embedding < q "]'::jsonb, '[0]'::jsonb, 'Oracle AI Vector Search natively integrates dense vector embeddings with relational tables, enabling hybrid searches combining SQL filters (WHERE clause) with semantic similarity. The correct choice is: Use specialized functions or libraries that calculate vector distances or similarities. .
Key Takeaway: Oracle 23ai runs vector similarity directly inside the database kernel alongside relational data.', 'Your answer is Correct.Explanation:  Direct comparison operations between vectors using operators like = or < are not supported and result in errors (ORA-22848). Therefore, options a) and b) are incorrect as they attempt to directly compare vectors using unsupported operators. Option d), while potentially feasible, is not recommended because string representations of vectors might not accurately reflect their underlying geometric or semantic relationships. The correct approach, as suggested by option c), involves utilizing specialized functions or libraries designed for vector similarity calculations. These functions often employ techniques like cosine similarity, Euclidean distance, or other distance metrics that are appropriate for measuring vector relationships.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('1034fc50-3430-5c49-9b6f-7152ffd6102a', 'e707974d-a436-58cc-ab4c-74638509a8ad', 'mcq'::public.question_type, 'mcq', 'What does the error message "ORA-22848: cannot use VECTOR type as comparison key" indicate?', '["The dimensionality of the vectors being compared is incompatible. ", "The query is trying to insert a vector with incorrect formatting.", "The VECTOR data type is not supported for indexing purposes. ", "An attempt was made to compare two vectors using operators like = or <. "]'::jsonb, '[3]'::jsonb, 'Oracle AI Vector Search natively integrates dense vector embeddings with relational tables, enabling hybrid searches combining SQL filters (WHERE clause) with semantic similarity. The correct choice is: An attempt was made to compare two vectors using operators like = or <. .
Key Takeaway: Oracle 23ai runs vector similarity directly inside the database kernel alongside relational data.', 'Your answer is Correct.Explanation:  Attempts to directly compare vectors using standard comparison operators result in this error. This highlights a key concept: vectors, unlike scalar values, cannot be directly compared using the usual relational operators in Oracle Database. Specialized functions or techniques are required for comparing vectors, such as calculating distances or similarities.'::public.difficulty_level, medium, 1);
INSERT INTO public.subtopics (id, course_id, name, order_index) VALUES ('9968d2fa-4cb2-5f4b-bc4f-c9f567f2c44d', '49eb4e03-fb89-51e7-96b8-960445d5a997', 'Vector Pool Architecture & Memory Sizing', 3);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('86731cd1-d7a9-5e79-a511-8d1c4a6a63f4', '9968d2fa-4cb2-5f4b-bc4f-c9f567f2c44d', 'mcq'::public.question_type, 'mcq', 'Where is the Vector Pool located within the Oracle Database 23ai architecture?', '["In the Program Global Area (PGA).", "In the System Global Area (SGA). ", "In the Database Buffer Cache. ", "In the Redo Log Buffer. "]'::jsonb, '[1]'::jsonb, 'Oracle AI Vector Search natively integrates dense vector embeddings with relational tables, enabling hybrid searches combining SQL filters (WHERE clause) with semantic similarity. The correct choice is: In the System Global Area (SGA). .
Key Takeaway: Oracle 23ai runs vector similarity directly inside the database kernel alongside relational data.', 'Your answer is Correct.Explanation: Vector Pool is a component within the System Global Area (SGA). The SGA is a shared memory region that holds data and control information for an Oracle Database instance.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('ddabac04-8868-55e4-b39a-25f73ccb878d', '9968d2fa-4cb2-5f4b-bc4f-c9f567f2c44d', 'mcq'::public.question_type, 'mcq', 'What is the approximate memory requirement (in GB) for an In-memory Neighbor Graph index with 1,000,000 rows, each represented by a vector with 1024 dimensions and a vector format size of 4 bytes?', '["About 5.0 GB ", "About 7.4 GB", "About 1.9 GB ", "About 3.7 GB "]'::jsonb, '[0]'::jsonb, 'Vector Index Types in Oracle AI Vector Search:
1. HNSW (Hierarchical Navigable Small World): Graph-based in-memory index providing high recall and fast approximate nearest neighbor (ANN) search with higher build time.
2. IVF (Inverted File Flat): Partition-based inverted list clustering index with lower memory footprint.
Correct answer: About 5.0 GB .
Key Takeaway: HNSW optimizes for query latency and recall; IVF optimizes for memory efficiency.', 'Your answer is Correct.Explanation: The formula for estimating the in-memory size of In-memory Neighbor Graph indexes is: 1.3 * Size of vector format * number of dimensions * number of rows. Applying the values from the question: 1.3 * 4 * 1024 * 1,000,000 = 5,324,800,000 bytes, which is approximately 5.0. The constant 1.3 accounts for overhead and graph layers.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('9e45b9df-7e10-5fac-97b6-ab7725d3696b', '9968d2fa-4cb2-5f4b-bc4f-c9f567f2c44d', 'mcq'::public.question_type, 'mcq', 'Which of the following is a recommended approach when there is insufficient RAM to accommodate large vector indexes?', '["Increase the size of the Redo Log Buffer. ", "Reduce the dimensionality of the vectors. ", "Disable the Vector Pool in the SGA.", "Utilize Inverted File Flat (IVF) indexes. "]'::jsonb, '[3]'::jsonb, 'Vector Index Types in Oracle AI Vector Search:
1. HNSW (Hierarchical Navigable Small World): Graph-based in-memory index providing high recall and fast approximate nearest neighbor (ANN) search with higher build time.
2. IVF (Inverted File Flat): Partition-based inverted list clustering index with lower memory footprint.
Correct answer: Utilize Inverted File Flat (IVF) indexes. .
Key Takeaway: HNSW optimizes for query latency and recall; IVF optimizes for memory efficiency.', 'Your answer is Correct.Explanation: It is recommended to use Inverted File Flat (IVF) indexes as an alternative when available RAM is insufficient to handle large vector indexes. IVF indexes leverage both the buffer cache and disk storage, making them more suitable for scenarios with RAM constraints.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('ba6647ff-c141-5ac7-9737-64bdab41802f', '9968d2fa-4cb2-5f4b-bc4f-c9f567f2c44d', 'mcq'::public.question_type, 'mcq', 'What is the significance of the VECTOR_MEMORY_SIZE parameter in Oracle Database 23ai?', '["It sets the precision of floating-point numbers used in vector computations.", "It determines the dimensionality of vectors that can be created. ", "It defines the maximum memory usage allowed for the Vector Pool in the SGA. ", "It limits the maximum number of vectors that can be stored in the Vector Pool. "]'::jsonb, '[2]'::jsonb, 'Oracle AI Vector Search natively integrates dense vector embeddings with relational tables, enabling hybrid searches combining SQL filters (WHERE clause) with semantic similarity. The correct choice is: It defines the maximum memory usage allowed for the Vector Pool in the SGA. .
Key Takeaway: Oracle 23ai runs vector similarity directly inside the database kernel alongside relational data.', 'Your answer is Correct.Explanation: VECTOR_MEMORY_SIZE is a parameter used to control the size of the Vector Pool. The parameter can be set at both the database (CDB) and pluggable database (PDB) levels. The value set for this parameter dictates the maximum amount of SGA memory that can be allocated to the Vector Pool, effectively limiting its size.4'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('abc9b767-272f-5f26-92e1-bc7cdff565d0', '9968d2fa-4cb2-5f4b-bc4f-c9f567f2c44d', 'mcq'::public.question_type, 'mcq', 'What is the primary function of a Vector Index in Oracle Database 23ai?', '["To store vector data directly on disk. ", "To efficiently search for vectors that are similar to a given query vector. ", "To calculate the dot product of two vectors.", "To convert traditional relational data into vector representations. "]'::jsonb, '[1]'::jsonb, 'Vector Index Types in Oracle AI Vector Search:
1. HNSW (Hierarchical Navigable Small World): Graph-based in-memory index providing high recall and fast approximate nearest neighbor (ANN) search with higher build time.
2. IVF (Inverted File Flat): Partition-based inverted list clustering index with lower memory footprint.
Correct answer: To efficiently search for vectors that are similar to a given query vector. .
Key Takeaway: HNSW optimizes for query latency and recall; IVF optimizes for memory efficiency.', 'Your answer is Correct.Explanation:  Vector Indexes are specialized indexing data structures designed to optimize vector search operations. These indexes employ techniques like clustering, partitioning, and neighbor graphs to significantly reduce the search space, enabling fast and efficient retrieval of similar vectors.'::public.difficulty_level, medium, 1);
INSERT INTO public.subtopics (id, course_id, name, order_index) VALUES ('59105d46-3de2-58f7-8220-228c41a42b7d', '49eb4e03-fb89-51e7-96b8-960445d5a997', 'Vector Dimensions & Data Definitions', 4);
