INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('a3b5b84b-a8ba-5eeb-a660-3c5eecf6a743', '81602b3c-c4bb-560f-8c2e-e4297cf6f59f', 'mcq'::public.question_type, 'mcq', 'Which SQL statement correctly adds a VECTOR column named v with 3 dimensions and FLOAT32 format to an existing table named my_table?', '["ALTER TABLE my_table MODIFY (v VECTOR(3, FLOAT32)) ", "UPDATE my_table SET v = VECTOR(3, FLOAT32)", "ALTER TABLE my_table ADD (v VECTOR(3, FLOAT32)) ", "ALTER TABLE my_table ADD v VECTOR(3, FLOAT32) "]'::jsonb, '[3]'::jsonb, 'Oracle AI Vector Search natively integrates dense vector embeddings with relational tables, enabling hybrid searches combining SQL filters (WHERE clause) with semantic similarity. The correct choice is: ALTER TABLE my_table ADD v VECTOR(3, FLOAT32) .
Key Takeaway: Oracle 23ai runs vector similarity directly inside the database kernel alongside relational data.', 'Your answer is Correct.Explanation: ALTER TABLE can be used to add a VECTOR column to an existing table.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
