INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('e267b041-75f5-55b8-9b51-69cb59f6d00f', '81602b3c-c4bb-560f-8c2e-e4297cf6f59f', 'mcq'::public.question_type, 'mcq', 'Which of the following statements is NOT true regarding operations on VECTOR columns?', '["You can perform direct comparisons between two VECTOR columns using operators like ''=''. ", "You can drop a VECTOR column from a table using ALTER TABLE... DROP COLUMN.", "You can use CTAS (Create Table As Select) to create a new table with a VECTOR column based on an existing table.", "You can update a VECTOR column based on the value of another column in the same table. "]'::jsonb, '[0]'::jsonb, 'Oracle AI Vector Search natively integrates dense vector embeddings with relational tables, enabling hybrid searches combining SQL filters (WHERE clause) with semantic similarity. The correct choice is: You can perform direct comparisons between two VECTOR columns using operators like ''=''. .
Key Takeaway: Oracle 23ai runs vector similarity directly inside the database kernel alongside relational data.', 'Your answer is Correct.Explanation: While most DML operations are permitted on tables and columns containing vectors, direct comparisons between vectors using operators like ''='' are not allowed.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('a3abca25-2cc5-557a-a6ee-27a822ec06ae', '81602b3c-c4bb-560f-8c2e-e4297cf6f59f', 'mcq'::public.question_type, 'mcq', 'Which of the following DDL operations is NOT permitted on a table containing a VECTOR column in Oracle Database 23ai?', '["Creating a new table using CREATE TABLE AS SELECT that includes the VECTOR column from the original table.", "Dropping an existing VECTOR column from the table. ", "Adding a new VECTOR column to the table. ", "Modifying the data type of an existing VECTOR column to a non-VECTOR type (e.g., VARCHAR2). "]'::jsonb, '[3]'::jsonb, 'Oracle AI Vector Search natively integrates dense vector embeddings with relational tables, enabling hybrid searches combining SQL filters (WHERE clause) with semantic similarity. The correct choice is: Modifying the data type of an existing VECTOR column to a non-VECTOR type (e.g., VARCHAR2). .
Key Takeaway: Oracle 23ai runs vector similarity directly inside the database kernel alongside relational data.', 'Your answer is Correct.Explanation: VECTOR column can be added to an existing table; VECTOR columns can be dropped, and CTAS can be used to create new tables that include VECTOR columns from existing tables. Directly changing a VECTOR column to a different data type is not permitted.'::public.difficulty_level, medium, 1);
INSERT INTO public.subtopics (id, course_id, name, order_index) VALUES ('549084a3-e35a-5f9d-8c3e-fb6e494c18ba', '49eb4e03-fb89-51e7-96b8-960445d5a997', 'Euclidean & Cosine Distance Calculations', 6);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('4c4c5583-58d0-5663-b365-8de0c4873198', '549084a3-e35a-5f9d-8c3e-fb6e494c18ba', 'mcq'::public.question_type, 'mcq', 'When adding a VECTOR column in a table, what additional information can you specify besides the column name?', '["The compression algorithm. ", "The default value for the column.", "The number of dimensions and the data type of the vector elements. ", "The storage size in bytes. "]'::jsonb, '[2]'::jsonb, 'Oracle AI Vector Search natively integrates dense vector embeddings with relational tables, enabling hybrid searches combining SQL filters (WHERE clause) with semantic similarity. The correct choice is: The number of dimensions and the data type of the vector elements. .
Key Takeaway: Oracle 23ai runs vector similarity directly inside the database kernel alongside relational data.', 'Your answer is Correct.Explanation: When adding a VECTOR column, you can specify the number of dimensions and the data type of the vector elements.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('b5fee1e7-66bd-52af-8d16-cfc27254cda4', '549084a3-e35a-5f9d-8c3e-fb6e494c18ba', 'mcq'::public.question_type, 'mcq', 'You need to find the Euclidean distance between the vectors (0, 0) and (3, 4). Which SQL statement will produce the correct result?', '["SELECT VECTOR_DISTANCE ((0, 0), (3, 4)) ", "SELECT EUCLIDEAN_DISTANCE (VECTOR(''[0,0]''), VECTOR(''[3,4]''))", "SELECT VECTOR_DISTANCE (VECTOR(''[0,0]''), VECTOR(''[3,4]''), EUCLIDEAN) ", "SELECT VECTOR_DISTANCE ('''', (3, 4)) "]'::jsonb, '[2]'::jsonb, 'Vector Distance Metrics in Oracle 23ai:
• COSINE: Measures angular similarity (range 0 to 2), ideal for semantic text embeddings regardless of vector magnitude.
• DOT (Inner Product): Computes dot product similarity, used when embeddings are unit-normalized.
• EUCLIDEAN (L2): Measures straight-line geometric distance between vector endpoints.
• MANHATTAN (L1): Sum of absolute coordinate differences.
Correct answer: SELECT VECTOR_DISTANCE (VECTOR(''[0,0]''), VECTOR(''[3,4]''), EUCLIDEAN) .
Key Takeaway: VECTOR_DISTANCE(v1, v2, ''COSINE'') is the standard metric for semantic text search in Oracle DB.', 'Your answer is Correct.Explanation: VECTOR_DISTANCE() takes three arguments:
The first vector, created using the VECTOR() constructor.The second vector, also created using the VECTOR() constructor.The distance metric to use, which is EUCLIDEAN in this case.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('04b6518e-f5ad-5bb6-bb87-9afbb7a4d7e4', '549084a3-e35a-5f9d-8c3e-fb6e494c18ba', 'mcq'::public.question_type, 'mcq', 'What is the primary purpose of the vector_distance() function in Oracle Database 23ai?', '["To determine the angle between two vectors. ", "To find the magnitude (length) of a single vector. ", "To calculate the dot product of two vectors. ", "To enable similarity searches by measuring the distance between vectors"]'::jsonb, '[3]'::jsonb, 'Vector Distance Metrics in Oracle 23ai:
• COSINE: Measures angular similarity (range 0 to 2), ideal for semantic text embeddings regardless of vector magnitude.
• DOT (Inner Product): Computes dot product similarity, used when embeddings are unit-normalized.
• EUCLIDEAN (L2): Measures straight-line geometric distance between vector endpoints.
• MANHATTAN (L1): Sum of absolute coordinate differences.
Correct answer: To enable similarity searches by measuring the distance between vectors.
Key Takeaway: VECTOR_DISTANCE(v1, v2, ''COSINE'') is the standard metric for semantic text search in Oracle DB.', 'Your answer is Correct.Explanation: vector_distance() enables similarity search by returning the distance between two vectors.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('93eed48d-4027-5e70-a63d-4ec6a1e18ab5', '549084a3-e35a-5f9d-8c3e-fb6e494c18ba', 'mcq'::public.question_type, 'mcq', 'You have a table named images with columns for image_id and a VECTOR column named feature_vector. You want to create a new table named image_subset that contains only the image_id and feature_vector columns for images with an image_id greater than 1000. Which SQL statement would achieve this?', '["INSERT INTO image_subset SELECT image_id, feature_vector FROM images WHERE image_id > 1000", "CREATE TABLE image_subset AS SELECT image_id, feature_vector FROM images WHERE image_id > 1000 ", "ALTER TABLE images CREATE TABLE image_subset AS SELECT image_id, feature_vector WHERE image_id > 1000 ", "COPY TABLE image_subset FROM images WHERE image_id > 1000"]'::jsonb, '[1]'::jsonb, 'Oracle AI Vector Search natively integrates dense vector embeddings with relational tables, enabling hybrid searches combining SQL filters (WHERE clause) with semantic similarity. The correct choice is: CREATE TABLE image_subset AS SELECT image_id, feature_vector FROM images WHERE image_id > 1000 .
Key Takeaway: Oracle 23ai runs vector similarity directly inside the database kernel alongside relational data.', 'Your answer is Correct.Explanation: A CTAS (Create Table As Select) statement can be used to create a new table from an existing table with a VECTOR column. Option (b) follows this correct syntax to create the image_subset table with the desired columns and data.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('247db713-9dfb-5f24-bd1f-1d1ddd25d7b2', '549084a3-e35a-5f9d-8c3e-fb6e494c18ba', 'mcq'::public.question_type, 'mcq', 'Which of the following SQL statements correctly creates a two-dimensional vector with the coordinates (4, -3) using the VECTOR() constructor?', '["SELECT VECTOR(4 -3)", "SELECT VECTOR(''(4, -3)'') ", "SELECT VECTOR(4, -3)", "SELECT VECTOR(''[4, -3]'') "]'::jsonb, '[3]'::jsonb, 'Oracle AI Vector Search natively integrates dense vector embeddings with relational tables, enabling hybrid searches combining SQL filters (WHERE clause) with semantic similarity. The correct choice is: SELECT VECTOR(''[4, -3]'') .
Key Takeaway: Oracle 23ai runs vector similarity directly inside the database kernel alongside relational data.', 'Your answer is Correct.Explanation: Vector coordinates are enclosed within square brackets [] and passed as a single string argument to the VECTOR() constructor.'::public.difficulty_level, medium, 1);
INSERT INTO public.subtopics (id, course_id, name, order_index) VALUES ('cfe512a3-5512-5133-8d75-3a18cc9dc7b9', '49eb4e03-fb89-51e7-96b8-960445d5a997', 'Exact vs Approximate Similarity Searches', 7);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('796bcc4d-97e1-512f-a494-bd012bda958b', 'cfe512a3-5512-5133-8d75-3a18cc9dc7b9', 'mcq'::public.question_type, 'mcq', 'What is a potential drawback of Exact Similarity Search?', '["Inaccurate results", "Limited accuracy", "Significant search times", "Use of vector indexes"]'::jsonb, '[2]'::jsonb, 'Technical Rationale: The correct answer is ''Significant search times''. In this scenario, ''Significant search times'' satisfies the architectural and operational requirements. Incorrect options (Inaccurate results, Limited accuracy) do not provide this exact capability.
Key Takeaway: Remember ''Significant search times'' as the standard exam pattern for this topic.', 'Your answer is Correct.Explanation: While Exact Similarity Search offers perfect search quality and the most accurate results, it can potentially result in significant search times.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('0e2dac8b-54cf-5eae-a65a-9b9efaaec645', 'cfe512a3-5512-5133-8d75-3a18cc9dc7b9', 'mcq'::public.question_type, 'mcq', 'Multi-Vector Similarity Search is typically used for:', '["Exact vector matching", "Multi-document search", "Single-vector comparisons", "Image recognition"]'::jsonb, '[1]'::jsonb, 'Oracle AI Vector Search natively integrates dense vector embeddings with relational tables, enabling hybrid searches combining SQL filters (WHERE clause) with semantic similarity. The correct choice is: Multi-document search.
Key Takeaway: Oracle 23ai runs vector similarity directly inside the database kernel alongside relational data.', 'Your answer is Correct.Explanation: Multi-Vector Similarity Search is primarily employed for searches involving multiple documents. In this approach, documents are divided into chunks, and each chunk is embedded into individual vectors for comparison and retrieval.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('6e35ac27-0751-5aa5-acea-7e55cb233be4', 'cfe512a3-5512-5133-8d75-3a18cc9dc7b9', 'mcq'::public.question_type, 'mcq', 'Which of the following is NOT a characteristic of Approximate Similarity Search?', '["Always provides exact matches", "Uses vector indexes", "Can be more efficient", "Uses target accuracy"]'::jsonb, '[0]'::jsonb, 'Technical Rationale: The correct answer is ''Always provides exact matches''. In this scenario, ''Always provides exact matches'' satisfies the architectural and operational requirements. Incorrect options (Uses vector indexes, Can be more efficient) do not provide this exact capability.
Key Takeaway: Remember ''Always provides exact matches'' as the standard exam pattern for this topic.', 'Your answer is Correct.Explanation: Approximate Similarity Search leverages vector indexes to enhance efficiency but may not always produce exact matches. It aims for a target accuracy level rather than perfect precision.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('9548d67c-0c1f-579a-bbda-932eeadd3020', 'cfe512a3-5512-5133-8d75-3a18cc9dc7b9', 'mcq'::public.question_type, 'mcq', 'What concept can be applied to vectorized data that is not uniformly distributed?', '["Dimensionality reduction", "Normalization ", "Indexing ", "Clustering "]'::jsonb, '[3]'::jsonb, 'Oracle AI Vector Search natively integrates dense vector embeddings with relational tables, enabling hybrid searches combining SQL filters (WHERE clause) with semantic similarity. The correct choice is: Clustering .
Key Takeaway: Oracle 23ai runs vector similarity directly inside the database kernel alongside relational data.', 'Your answer is Correct.Explanation: Vectorized data can form clusters, representing groups of similar data. These clusters arise because the data is not evenly spread out (uniformly distributed).'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('a887e3e4-337d-5593-9d3d-83b13eaa841e', 'cfe512a3-5512-5133-8d75-3a18cc9dc7b9', 'mcq'::public.question_type, 'mcq', 'Based on the sources, which of these is a valid way to construct a vector with the values (10, 20) using the VECTOR() constructor?', '["VECTOR [''10, 20''] ", "VECTOR ( [10,  20] ) ", "VECTOR (10, 20) ", "<p>VECTOR ( ''[10, 20]'' )&nbsp;</p>"]'::jsonb, '[3]'::jsonb, 'Oracle AI Vector Search natively integrates dense vector embeddings with relational tables, enabling hybrid searches combining SQL filters (WHERE clause) with semantic similarity. The correct choice is: <p>VECTOR ( ''[10, 20]'' )&nbsp;</p>.
Key Takeaway: Oracle 23ai runs vector similarity directly inside the database kernel alongside relational data.', 'Your answer is Correct.Explanation: VECTOR ( ''[value1, value2]'' ) is used to create vectors. Square brackets and commas are used within the string to delimit the vector values. The other options do not follow the syntax required to create vectors.'::public.difficulty_level, medium, 1);
INSERT INTO public.subtopics (id, course_id, name, order_index) VALUES ('709a2bc2-0604-5657-a027-a36a4151e547', '49eb4e03-fb89-51e7-96b8-960445d5a997', 'Multi-Vector Searches & Similarity Queries', 8);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('7a76d136-be1b-55f0-aa28-b36e16c7a73f', '709a2bc2-0604-5657-a027-a36a4151e547', 'mcq'::public.question_type, 'mcq', 'Assuming we have a table called VT2 that contains vectors for mapping various shapes, colors, and sizes, what is the primary purpose of the following UPDATE statements?SQL> UPDATE vt2SET shape = ''Triangle''WHERE id IN (2, 4, 7, 22, 31, 41, 44, 55); SQL> UPDATE vt2SET size = ''Medium''WHERE id IN (5, 22, 25, 32, 34, 42, 43, 53, 54, 55);', '["To delete rows from the VT2 table that do not meet specific criteria.", "To add new rows of data to the VT2 table with different sizes and shapes. ", "To modify the vector values stored in the VT2 table. ", "To assign attributes like size and shape to existing vectors based on their IDs. "]'::jsonb, '[3]'::jsonb, 'Oracle AI Vector Search natively integrates dense vector embeddings with relational tables, enabling hybrid searches combining SQL filters (WHERE clause) with semantic similarity. The correct choice is: To assign attributes like size and shape to existing vectors based on their IDs. .
Key Takeaway: Oracle 23ai runs vector similarity directly inside the database kernel alongside relational data.', 'Your answer is Correct.Explanation: The UPDATE statements are used to populate the SIZE and SHAPE columns of the VT2 table. These columns are added to the table to store attributes associated with each vector. The UPDATE statements use WHERE clauses to selectively modify rows based on their ID, linking specific attributes to corresponding vectors.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('03e2a7f0-2360-58f1-97b7-7e994cf0ab7b', '709a2bc2-0604-5657-a027-a36a4151e547', 'mcq'::public.question_type, 'mcq', 'What is Exact Similarity Search also called?', '["Flat search", "Vector search", "Approximate search", "Efficient search"]'::jsonb, '[0]'::jsonb, 'Technical Rationale: The correct answer is ''Flat search''. In this scenario, ''Flat search'' satisfies the architectural and operational requirements. Incorrect options (Vector search, Approximate search) do not provide this exact capability.
Key Takeaway: Remember ''Flat search'' as the standard exam pattern for this topic.', 'Your answer is Correct.Explanation: Exact Similarity Search is also referred to as Flat Search.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('29b83259-bff2-548f-bc39-80d5f43102ee', '709a2bc2-0604-5657-a027-a36a4151e547', 'mcq'::public.question_type, 'mcq', 'What is the primary purpose of using the VECTOR_DISTANCE() function in a SQL query?', '["To determine the geometric shape of the data points.", "To group data points based on their color attributes.", "To sort the results in ascending order of their IDs.", "To calculate the distance between vectors for similarity comparison."]'::jsonb, '[3]'::jsonb, 'Vector Distance Metrics in Oracle 23ai:
• COSINE: Measures angular similarity (range 0 to 2), ideal for semantic text embeddings regardless of vector magnitude.
• DOT (Inner Product): Computes dot product similarity, used when embeddings are unit-normalized.
• EUCLIDEAN (L2): Measures straight-line geometric distance between vector endpoints.
• MANHATTAN (L1): Sum of absolute coordinate differences.
Correct answer: To calculate the distance between vectors for similarity comparison..
Key Takeaway: VECTOR_DISTANCE(v1, v2, ''COSINE'') is the standard metric for semantic text search in Oracle DB.', 'Your answer is Correct.Explanation: The VECTOR_DISTANCE() function is used to compute the distance between vectors, which serves as a measure of similarity. This distance calculation is crucial for finding the closest vectors to the target vector.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('1528dda3-a14e-5f5b-87ee-82151532f336', '709a2bc2-0604-5657-a027-a36a4151e547', 'mcq'::public.question_type, 'mcq', 'In the following SQL query, which distance function should replace the FUNCTION keyword to find the closest vectors?SQL> SELECT id, vsize, shape, color,      to_number(Function(vector(''[16, 3]''), v, EUCLIDEAN)) distance     FROM   vt2     WHERE  id > 30 AND id < 40     ORDER  BY vector_distance(vector(''[16, 3]''), v, EUCLIDEAN)     FETCH FIRST 3 ROWS ONLY;', '["inner_product ", "cosine_distance ", "vector_distance", "L1_distance"]'::jsonb, '[2]'::jsonb, 'Vector Distance Metrics in Oracle 23ai:
• COSINE: Measures angular similarity (range 0 to 2), ideal for semantic text embeddings regardless of vector magnitude.
• DOT (Inner Product): Computes dot product similarity, used when embeddings are unit-normalized.
• EUCLIDEAN (L2): Measures straight-line geometric distance between vector endpoints.
• MANHATTAN (L1): Sum of absolute coordinate differences.
Correct answer: vector_distance.
Key Takeaway: VECTOR_DISTANCE(v1, v2, ''COSINE'') is the standard metric for semantic text search in Oracle DB.', 'Your answer is Correct.Explanation: vector_distance calculates the distance between two vectors using a specific metric (like Euclidean distance). It is the most appropriate choice for finding the closest vectors. cosine_distance measures the cosine of the angle between two vectors, which is useful for understanding the orientation of the vectors rather than their absolute distances. It is not suitable for finding the "closest" vectors in terms of Euclidean distance. inner_product computes the dot product of two vectors. While it can provide some insights into the similarity of the vectors, it does not directly measure distance. L1_distance, also known as Manhattan distance, sums the absolute differences of their coordinates. While it''s another way to measure distance, the query specifies using Euclidean distance, making this option less suitable in this context.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('1bdf5481-43fd-5e82-9de0-18fa458d0b90', '709a2bc2-0604-5657-a027-a36a4151e547', 'mcq'::public.question_type, 'mcq', 'What data types can be used for the components of a VECTOR column in Oracle Database 23ai?', '["Both NUMBER and FLOAT", "VARCHAR2 only ", "NUMBER only ", "FLOAT only "]'::jsonb, '[0]'::jsonb, 'Oracle AI Vector Search natively integrates dense vector embeddings with relational tables, enabling hybrid searches combining SQL filters (WHERE clause) with semantic similarity. The correct choice is: Both NUMBER and FLOAT.
Key Takeaway: Oracle 23ai runs vector similarity directly inside the database kernel alongside relational data.', 'Your answer is Correct.Explanation: VECTOR() constructor can be used with both NUMBER and FLOAT data types for the vector elements. E.g., VECTOR('''', 2, FLOAT32) uses a FLOAT data type. Implicitly, when no data type is specified, the examples suggest that NUMBER is the assumed data type.'::public.difficulty_level, medium, 1);
INSERT INTO public.subtopics (id, course_id, name, order_index) VALUES ('c5e144ff-3c7d-5b51-a136-95812f43c978', '49eb4e03-fb89-51e7-96b8-960445d5a997', 'Vector Distance Functions & Shorthands', 9);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('273af2a2-4957-5003-98c5-8722b60dea95', 'c5e144ff-3c7d-5b51-a136-95812f43c978', 'mcq'::public.question_type, 'mcq', 'Which vector distance function is equivalent to using the shorthand syntax v1 <-> v2 in Oracle Database 23ai?', '["L1_DISTANCE (v1, v2) ", "INNER_PRODUCT (v1, v2) ", "L2_DISTANCE (v1, v2)", "COSINE_DISTANCE (v1, v2) "]'::jsonb, '[2]'::jsonb, 'Vector Distance Metrics in Oracle 23ai:
• COSINE: Measures angular similarity (range 0 to 2), ideal for semantic text embeddings regardless of vector magnitude.
• DOT (Inner Product): Computes dot product similarity, used when embeddings are unit-normalized.
• EUCLIDEAN (L2): Measures straight-line geometric distance between vector endpoints.
• MANHATTAN (L1): Sum of absolute coordinate differences.
Correct answer: L2_DISTANCE (v1, v2).
Key Takeaway: VECTOR_DISTANCE(v1, v2, ''COSINE'') is the standard metric for semantic text search in Oracle DB.', 'Your answer is Correct.Explanation: The operator <-> represents the Euclidean distance between vectors. The L2_DISTANCE() function is also defined as calculating the Euclidean distance.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('7a4c15c8-d347-52ab-a07f-7f54db6d17e1', 'c5e144ff-3c7d-5b51-a136-95812f43c978', 'mcq'::public.question_type, 'mcq', 'What is the purpose of using alternative distance functions like cosine similarity, dot product, or Manhattan distance when comparing vectors?', '["To normalize the vectors before calculating distances, ensuring fair comparisons.", "To handle cases where the vectors have missing or incomplete data. ", "To measure different aspects of similarity or dissimilarity between vectors, beyond Euclidean distance. ", "To improve the speed of vector comparisons, especially for high-dimensional vectors. "]'::jsonb, '[2]'::jsonb, 'Vector Distance Metrics in Oracle 23ai:
• COSINE: Measures angular similarity (range 0 to 2), ideal for semantic text embeddings regardless of vector magnitude.
• DOT (Inner Product): Computes dot product similarity, used when embeddings are unit-normalized.
• EUCLIDEAN (L2): Measures straight-line geometric distance between vector endpoints.
• MANHATTAN (L1): Sum of absolute coordinate differences.
Correct answer: To measure different aspects of similarity or dissimilarity between vectors, beyond Euclidean distance. .
Key Takeaway: VECTOR_DISTANCE(v1, v2, ''COSINE'') is the standard metric for semantic text search in Oracle DB.', 'Your answer is Correct.Explanation: Various distance functions offer different ways to assess vector relationships. For instance, cosine similarity focuses on the angle between vectors, while dot product considers the magnitude and direction. The choice of distance function depends on the specific application and how similarity is defined in that context.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('22cc1b17-6ae2-5584-9d85-13cd4eaae64e', 'c5e144ff-3c7d-5b51-a136-95812f43c978', 'mcq'::public.question_type, 'mcq', 'What is the main advantage of using the shorthand syntax like <-> or <#> for vector distance calculations?', '["It allows for more complex mathematical operations within the distance calculation. ", "It enables the use of custom-defined distance functions.", "It improves the readability and conciseness of the SQL queries. ", "It reduces the computational overhead of vector comparisons. "]'::jsonb, '[2]'::jsonb, 'Vector Distance Metrics in Oracle 23ai:
• COSINE: Measures angular similarity (range 0 to 2), ideal for semantic text embeddings regardless of vector magnitude.
• DOT (Inner Product): Computes dot product similarity, used when embeddings are unit-normalized.
• EUCLIDEAN (L2): Measures straight-line geometric distance between vector endpoints.
• MANHATTAN (L1): Sum of absolute coordinate differences.
Correct answer: It improves the readability and conciseness of the SQL queries. .
Key Takeaway: VECTOR_DISTANCE(v1, v2, ''COSINE'') is the standard metric for semantic text search in Oracle DB.', 'Your answer is Correct.Explanation: Shorthand syntax can be used as an alternative to the more verbose VECTOR_DISTANCE() function. Using operators like <-> or <#> can make the queries more compact and easier to understand, especially when performing multiple vector comparisons.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('a181c3ab-32d1-5c7e-8e0c-c5eae7434388', 'c5e144ff-3c7d-5b51-a136-95812f43c978', 'mcq'::public.question_type, 'mcq', 'Which of the following shorthand notations in Oracle Database 23ai represents the cosine similarity between two vectors, v1 and v2?', '["v1 <#> v2 ", "v1 <=> v2 ", "v1 <+> v2", "v1 <-> v2 "]'::jsonb, '[1]'::jsonb, 'Vector Distance Metrics in Oracle 23ai:
• COSINE: Measures angular similarity (range 0 to 2), ideal for semantic text embeddings regardless of vector magnitude.
• DOT (Inner Product): Computes dot product similarity, used when embeddings are unit-normalized.
• EUCLIDEAN (L2): Measures straight-line geometric distance between vector endpoints.
• MANHATTAN (L1): Sum of absolute coordinate differences.
Correct answer: v1 <=> v2 .
Key Takeaway: VECTOR_DISTANCE(v1, v2, ''COSINE'') is the standard metric for semantic text search in Oracle DB.', 'Your answer is Correct.Explanation: The operator <=> is explicitly defined as equivalent to the cosine similarity distance function. The other options represent different distance metrics:


<-> corresponds to Euclidean distance.
<#> represents the negative dot product.4
<+> is not a valid shorthand notation for vector distances in the sources.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('23d5377c-eb14-59d7-a5ba-d83373e2b066', 'c5e144ff-3c7d-5b51-a136-95812f43c978', 'mcq'::public.question_type, 'mcq', 'If the VECTOR_DISTANCE() function is used with the HAMMING metric, what characteristic of the vectors is being compared?', '["The sum of the absolute differences between corresponding components. ", "The angle between the vectors. ", "The number of components that have different values. ", "The product of the corresponding components."]'::jsonb, '[2]'::jsonb, 'Vector Distance Metrics in Oracle 23ai:
• COSINE: Measures angular similarity (range 0 to 2), ideal for semantic text embeddings regardless of vector magnitude.
• DOT (Inner Product): Computes dot product similarity, used when embeddings are unit-normalized.
• EUCLIDEAN (L2): Measures straight-line geometric distance between vector endpoints.
• MANHATTAN (L1): Sum of absolute coordinate differences.
Correct answer: The number of components that have different values. .
Key Takeaway: VECTOR_DISTANCE(v1, v2, ''COSINE'') is the standard metric for semantic text search in Oracle DB.', 'Your answer is Correct.Explanation: The Hamming distance is a measure of dissimilarity between two strings of equal length. It counts the number of positions at which the corresponding symbols are different.'::public.difficulty_level, medium, 1);
INSERT INTO public.subtopics (id, course_id, name, order_index) VALUES ('96472c98-c795-5ba1-914b-e363753a058c', '49eb4e03-fb89-51e7-96b8-960445d5a997', 'Vector Format Queries & Error Handling', 10);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('cf6221a4-b4b2-5826-97af-5c429649702b', '96472c98-c795-5ba1-914b-e363753a058c', 'mcq'::public.question_type, 'mcq', 'Which of the following actions will result in an error when using VECTOR_DIMENSION_COUNT() in Oracle Database 23ai?', '["Providing a vector with a dimensionality that exceeds the specified dimension count. ", "Calling the function on a vector that has been created with to_vector().", "Providing a vector with duplicate values for its components. ", "Using a vector with a data type that is not supported by the function. "]'::jsonb, '[0]'::jsonb, 'Oracle AI Vector Search natively integrates dense vector embeddings with relational tables, enabling hybrid searches combining SQL filters (WHERE clause) with semantic similarity. The correct choice is: Providing a vector with a dimensionality that exceeds the specified dimension count. .
Key Takeaway: Oracle 23ai runs vector similarity directly inside the database kernel alongside relational data.', 'Your answer is Correct.Explanation: VECTOR_DIMENSION_COUNT() will throw an error (ORA-51803) if the vector''s actual dimension count does not match the dimension count specified in the function call. This error is not triggered by other factors like data type, duplicate values, or the vector''s creation method.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('6774f9c2-f334-55d7-8f88-e263a8183ff9', '96472c98-c795-5ba1-914b-e363753a058c', 'mcq'::public.question_type, 'mcq', 'Which SQL statement correctly retrieves the format of the numbers stored in the vector ''''[34.6, 77.8, 9, 10]''1'' using the vector_dimension_format () function in Oracle Database 23ai?', '["<p>SELECT vector_dimension_format(vector(\u2018[34.6, 77.8, 9, 10]\u2019,4, INT8)) FROM dual;</p>", "SELECT vector_dimension_format (34.6, 77.8, 9, 10) FROM dual ", "SELECT vector_dimension_format ( 34.6, 77.8, 9, 10, 3 ''1'') FROM dual", "SELECT vector_dimension_format (''INT8'') FROM dual;"]'::jsonb, '[0]'::jsonb, 'Oracle AI Vector Search natively integrates dense vector embeddings with relational tables, enabling hybrid searches combining SQL filters (WHERE clause) with semantic similarity. The correct choice is: <p>SELECT vector_dimension_format(vector(‘[34.6, 77.8, 9, 10]’,4, INT8)) FROM dual;</p>.
Key Takeaway: Oracle 23ai runs vector similarity directly inside the database kernel alongside relational data.', 'Your answer is Correct.Explanation: The correct syntax is vector_dimension_format (vector(''[34.6, 77.8, 9, 10]'', 4, INT8)). The other options are incorrect because:Option a) passes a string literal directly to the function, not a vector object.Option c) attempts to pass individual numeric values, not a vector.Option d) provides a string literal ''INT8'', which is not the correct way to determine the vector''s format. The format is determined by the data type used when creating the vector, not by a separate string input.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('6c729c45-835b-5b9e-be53-bbc558fab604', '96472c98-c795-5ba1-914b-e363753a058c', 'mcq'::public.question_type, 'mcq', 'What is the primary purpose of the VECTOR_NORM() function in Oracle Database 23ai?', '["To calculate the Euclidean distance between two vectors. ", "To convert a vector to a string representation.", "To determine the number of dimensions in a vector. ", "To return the magnitude or length of a vector. "]'::jsonb, '[3]'::jsonb, 'Oracle AI Vector Search natively integrates dense vector embeddings with relational tables, enabling hybrid searches combining SQL filters (WHERE clause) with semantic similarity. The correct choice is: To return the magnitude or length of a vector. .
Key Takeaway: Oracle 23ai runs vector similarity directly inside the database kernel alongside relational data.', 'Your answer is Correct.Explanation: VECTOR_NORM() calculates the "distance from the origin to the vector," which is synonymous with the vector''s magnitude or length. This function is distinct from distance functions like VECTOR_DISTANCE() or shorthand operators like <->, which calculate the distance between two vectors.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('93e40155-585e-5e1e-bf7b-dc8219dc7a90', '96472c98-c795-5ba1-914b-e363753a058c', 'mcq'::public.question_type, 'mcq', 'Which of the following SQL statements demonstrates the correct usage of the to_vector() function in Oracle Database 23ai?', '["SELECT to_vector(34.6, 77.8, 2, float32) FROM dual ", "SELECT to_vector([34.6, 77.8], 2, float32) FROM dual", "SELECT to_vector(''[34.6, 77.8]'', 2, float32) FROM dual ", "SELECT to_vector(''34.6, 77.8'', 2, float32) FROM dual "]'::jsonb, '[2]'::jsonb, 'Oracle AI Vector Search natively integrates dense vector embeddings with relational tables, enabling hybrid searches combining SQL filters (WHERE clause) with semantic similarity. The correct choice is: SELECT to_vector(''[34.6, 77.8]'', 2, float32) FROM dual .
Key Takeaway: Oracle 23ai runs vector similarity directly inside the database kernel alongside relational data.', 'Your answer is Correct.Explanation: to_vector() function can be used with a string representation of the vector enclosed in square brackets. The format is to_vector(''[value1, value2, ...]'', dimension_count, data_type). Options a), c), and d) use incorrect syntax. Option a) provides individual values instead of a string representation. Option c) lacks the square brackets. Option d) uses an array-like notation which is not supported for vector creation in the sources.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('a47f1b49-6779-5d64-a209-9e6297e90b5d', '96472c98-c795-5ba1-914b-e363753a058c', 'mcq'::public.question_type, 'mcq', 'What is the primary purpose of the VECTOR_SERIALIZE() function in Oracle Database 23ai, as presented in the sources?', '["To create a new vector from a string representation.", "To calculate the distance between two vectors. ", "To determine the number of dimensions in a vector. ", "To convert a vector to a string or CLOB data type. "]'::jsonb, '[3]'::jsonb, 'Oracle AI Vector Search natively integrates dense vector embeddings with relational tables, enabling hybrid searches combining SQL filters (WHERE clause) with semantic similarity. The correct choice is: To convert a vector to a string or CLOB data type. .
Key Takeaway: Oracle 23ai runs vector similarity directly inside the database kernel alongside relational data.', 'Your answer is Correct.Explanation: VECTOR_SERIALIZE() can convert a vector to a string or CLOB data type. The function can optionally specify the target data type using the returning clause, such as returning varchar2(1000) or returning CLOB. This function is distinct from to_vector(), which converts a string representation to a vector.'::public.difficulty_level, medium, 1);

