INSERT INTO public.courses (id, name, description, icon) VALUES ('73e8a5d1-0dd3-55fa-b9d7-b171ef5e7428', 'OCI Data Science Professional', 'Master OCI Data Science lifecycle, notebook sessions, conda environments, AutoML, MLOps, and pipeline execution.', 'bar-chart');
INSERT INTO public.subtopics (id, course_id, name, order_index) VALUES ('b937bbd2-13fa-5404-b17a-dc7e0e90daaf', '73e8a5d1-0dd3-55fa-b9d7-b171ef5e7428', 'Introduction & Configuration', 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('ebb28454-6e02-5586-a3b3-8856e9b0fe68', 'b937bbd2-13fa-5404-b17a-dc7e0e90daaf', 'mcq'::public.question_type, 'mcq', 'Where are OCI secrets stored?', '["Oracle Databases", "Autonomous Data Warehouse", "OCI Vault", "OCI Object Storage"]'::jsonb, '[2]'::jsonb, 'Technical Rationale: The correct answer is ''OCI Vault''. In this scenario, ''OCI Vault'' satisfies the architectural and operational requirements. Incorrect options (Oracle Databases, Autonomous Data Warehouse) do not provide this exact capability.
Key Takeaway: Remember ''OCI Vault'' as the standard exam pattern for this topic.', 'Secrets are credentials such as passwords or tokens--or any other confidential data that you need to use with other Oracle Cloud Infrastructure services--or perhaps even other external applications or systems. They are stored in OCI Vault.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('07b15bd2-1ec6-5d22-a3c8-2470c1c82fca', 'b937bbd2-13fa-5404-b17a-dc7e0e90daaf', 'mcq'::public.question_type, 'mcq', 'Which activity of managing a conda environment requires the conda environment to be activated in your terminal?', '["Installing a Conda environment", "Publishing a Conda environment", "Cloning a Conda environment", "Modifying a Conda environment"]'::jsonb, '[3]'::jsonb, 'OCI Data Science Conda Environments:
• Pre-built (curated) environments support popular frameworks (PyTorch, TensorFlow, Scikit-learn, ONNX).
• Custom conda environments can be published to OCI Object Storage and shared across notebook sessions, jobs, and model deployments using the ''odsc conda'' CLI.
Correct answer: Modifying a Conda environment.
Key Takeaway: Publishing custom conda environments to Object Storage ensures reproducible ML workflows across OCI.', 'To modify the libraries in the Conda environment, it must remain active.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('a065b7e3-161d-5ebd-9664-9ddc33a7d7c0', 'b937bbd2-13fa-5404-b17a-dc7e0e90daaf', 'mcq'::public.question_type, 'mcq', 'Which model has an open source, open model format that allows you to run machine learning models on different platforms?', '["PySpark", "ONNX", "PyTorch", "TensorFlow"]'::jsonb, '[1]'::jsonb, 'Technical Rationale: The correct answer is ''ONNX''. In this scenario, ''ONNX'' satisfies the architectural and operational requirements. Incorrect options (PySpark, PyTorch) do not provide this exact capability.
Key Takeaway: Remember ''ONNX'' as the standard exam pattern for this topic.', 'ONNX is an open source, open model package that allows you to save a model from different machine learning (ML) libraries into a single, portable format that is independent of the training library. TensorFlow and PyTorch are open source ML frameworks for deep neural networks. PySpark is a framework used for processing a huge amount of data.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('a3bc0222-921b-5b0d-843e-2223fbb81508', 'b937bbd2-13fa-5404-b17a-dc7e0e90daaf', 'mcq'::public.question_type, 'mcq', 'Which CLI command allows a customized Conda environment to be shared with co-workers?', '["odsc conda clone", "odsc conda install", "odsc conda modify", "odsc conda publish"]'::jsonb, '[3]'::jsonb, 'OCI Data Science Conda Environments:
• Pre-built (curated) environments support popular frameworks (PyTorch, TensorFlow, Scikit-learn, ONNX).
• Custom conda environments can be published to OCI Object Storage and shared across notebook sessions, jobs, and model deployments using the ''odsc conda'' CLI.
Correct answer: odsc conda publish.
Key Takeaway: Publishing custom conda environments to Object Storage ensures reproducible ML workflows across OCI.', 'Publishing a Conda environment consists of creating a pack of a Conda environment and uploading it to a specified Object Storage. This allows Conda environments to be shared among colleagues or to persist them across Notebook sessions.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('5b1b063b-72cd-5947-8851-292f4cff0878', 'b937bbd2-13fa-5404-b17a-dc7e0e90daaf', 'mcq'::public.question_type, 'mcq', 'What happens when a notebook session is deactivated?', '["Compute cost increases due to frequent deactivation.", "The data on the boot volume is not preserved.", "The block volume attached to the Notebook session is permanently deleted.", "The underlying compute instance stops."]'::jsonb, '[3]'::jsonb, 'In OCI Data Science Professional, The underlying compute instance stops. represents the standard architecture pattern for managing scalable MLOps lifecycle from experimentation to production deployment.
Key Takeaway: OCI Data Science streamlines collaborative ML pipelines using managed compute and Object Storage.', 'When you deactivate a Notebook session, you save on compute costs because the underlying compute instance stops, and the block volume is detached and preserved.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('bfaa8ecc-55d6-5f05-a5a1-66184c03de06', 'b937bbd2-13fa-5404-b17a-dc7e0e90daaf', 'mcq'::public.question_type, 'mcq', 'What is an accurate description of Git?', '["Git is a centralized version control system that allows data scientists and developers to track copious amounts of data.", "Git is a distributed version control system that protects teams from simultaneous repo contributions and merge requests.", "Git is a centralized version control system that allows you to revert to previous versions of files as needed.", "Git is a distributed version control system that allows you to track changes made to a set of files."]'::jsonb, '[3]'::jsonb, 'Technical Rationale: The correct answer is ''Git is a distributed version control system that allows you to track changes made to a set of files.''. In this scenario, ''Git is a distributed version control system that allows you to track changes made to a set of files.'' satisfies the architectural and operational requirements. Incorrect options (Git is a centralized version control system that allows data scientists and developers to track copious amounts of data., Git is a distributed version control system that protects teams from simultaneous repo contributions and merge requests.) do not provide this exact capability.
Key Takeaway: Remember ''Git is a distributed version control system that allows you to track changes made to a set of files.'' as the standard exam pattern for this topic.', 'Git is a distributed version control system in which you clone the entire remote (or central) repository, including its history, to your computer. You add and commit the files on your computer and, when you are done, push the commits to the remote repository.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('2396e749-f4ef-5c5f-b1a7-7dea1de92f04', 'b937bbd2-13fa-5404-b17a-dc7e0e90daaf', 'mcq'::public.question_type, 'mcq', 'Which is a unique feature of the published Conda environment?', '["It allows you to save the Conda environment to an Object Storage bucket.", "It provides a comprehensive environment to solve business use cases.", "It allows you to save the Conda environment in a block volume.", "It provides availability on Notebook session reactivation."]'::jsonb, '[0]'::jsonb, 'OCI Data Science Conda Environments:
• Pre-built (curated) environments support popular frameworks (PyTorch, TensorFlow, Scikit-learn, ONNX).
• Custom conda environments can be published to OCI Object Storage and shared across notebook sessions, jobs, and model deployments using the ''odsc conda'' CLI.
Correct answer: It allows you to save the Conda environment to an Object Storage bucket..
Key Takeaway: Publishing custom conda environments to Object Storage ensures reproducible ML workflows across OCI.', 'Published Conda environments are customer-created and saved to Object Storage buckets. This is the most unique feature of the published Conda environment.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('5f1a7970-a56b-551d-8f19-eac830a8a638', 'b937bbd2-13fa-5404-b17a-dc7e0e90daaf', 'mcq'::public.question_type, 'mcq', 'What is a conda environment?', '["An\u00a0environment\u00a0deployment\u00a0system\u00a0on\u00a0Oracle\u00a0AI", "A collection of kernels", "An open source package and environment management system", "A\u00a0system\u00a0that\u00a0manages\u00a0package\u00a0independencies\u00a0"]'::jsonb, '[2]'::jsonb, 'OCI Data Science Conda Environments:
• Pre-built (curated) environments support popular frameworks (PyTorch, TensorFlow, Scikit-learn, ONNX).
• Custom conda environments can be published to OCI Object Storage and shared across notebook sessions, jobs, and model deployments using the ''odsc conda'' CLI.
Correct answer: An open source package and environment management system.
Key Takeaway: Publishing custom conda environments to Object Storage ensures reproducible ML workflows across OCI.', 'Conda is an open source package management system and environment management system. Conda as a package manager helps you find and install packages.'::public.difficulty_level, medium, 1);
INSERT INTO public.subtopics (id, course_id, name, order_index) VALUES ('1ca38105-d2e8-53d2-9f45-1c1db4957b1f', '73e8a5d1-0dd3-55fa-b9d7-b171ef5e7428', 'Workspace Design & Setup', 2);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('c3ff3d95-ad97-5221-b2b2-78435c6c1be4', '1ca38105-d2e8-53d2-9f45-1c1db4957b1f', 'mcq'::public.question_type, 'mcq', 'You are working for a bank. You are required to analyze customer accounts'' access data and flag any irregular access attempts. Which OCI Data Science operator are you most likely to use?', '["PII", "Forecasting", "Anomaly"]'::jsonb, '[2]'::jsonb, 'Technical Rationale: The correct answer is ''Anomaly''. In this scenario, ''Anomaly'' satisfies the architectural and operational requirements. Incorrect options (PII, Forecasting) do not provide this exact capability.
Key Takeaway: Remember ''Anomaly'' as the standard exam pattern for this topic.', 'Anomaly detection is used for finding anomalies or any irregularities in your data.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('8b3de381-f301-5780-98e4-f2a454fc7e5e', '1ca38105-d2e8-53d2-9f45-1c1db4957b1f', 'mcq'::public.question_type, 'mcq', 'Which activity is NOT a part of the machine learning life cycle?', '["Modeling", "Database Management", "Model Deployment", "Data Access"]'::jsonb, '[1]'::jsonb, 'Technical Rationale: The correct answer is ''Database Management''. In this scenario, ''Database Management'' satisfies the architectural and operational requirements. Incorrect options (Modeling, Model Deployment) do not provide this exact capability.
Key Takeaway: Remember ''Database Management'' as the standard exam pattern for this topic.', 'The machine learning life cycle has six important tasks: Data Access, Data Exploration and Data Preparation, Modeling, Validation, Model Deployment, and Monitoring/Refresh/Retirement. Database Management is not a part of this life cycle.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('2a89b03c-1fef-586a-a5e9-ec3fd2fc05fe', '1ca38105-d2e8-53d2-9f45-1c1db4957b1f', 'mcq'::public.question_type, 'mcq', 'Which step is a part of AutoML pipeline?', '["Model Saved to Model Catalog", "Feature Selection", "Model Deployment", "Feature Extraction"]'::jsonb, '[1]'::jsonb, 'In OCI Data Science Professional, Feature Selection represents the standard architecture pattern for managing scalable MLOps lifecycle from experimentation to production deployment.
Key Takeaway: OCI Data Science streamlines collaborative ML pipelines using managed compute and Object Storage.', 'Oracle AutoML automates four major steps in the machine learning modeling process to deliver significant productivity improvements for data scientists. They are Algorithm Selection, Adaptive Sampling, Feature Selection, and Model Tuning.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('67cd62f9-4315-5343-8f81-9bb4da79ce8e', '1ca38105-d2e8-53d2-9f45-1c1db4957b1f', 'mcq'::public.question_type, 'mcq', 'Which function represents the difference between the predictive value and the target value?', '["Cost function", "Fit function", "Optimizer function", "Update function"]'::jsonb, '[0]'::jsonb, 'Technical Rationale: The correct answer is ''Cost function''. In this scenario, ''Cost function'' satisfies the architectural and operational requirements. Incorrect options (Fit function, Optimizer function) do not provide this exact capability.
Key Takeaway: Remember ''Cost function'' as the standard exam pattern for this topic.', 'The objective of the loss function is to represent the difference between the predicted values Ŷ and the true targets Y as a single number, the loss score. The loss function is also known as the cost function.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('e5e13f85-1141-5d49-aa1d-d82d9f602d3f', '1ca38105-d2e8-53d2-9f45-1c1db4957b1f', 'mcq'::public.question_type, 'mcq', 'What do you use the score.py file for?', '["Defining the scaling strategy", "Defining the required Conda environments", "Executing the inference logic code", "Configuring the deployment infrastructure"]'::jsonb, '[2]'::jsonb, 'Technical Rationale: The correct answer is ''Executing the inference logic code''. In this scenario, ''Executing the inference logic code'' satisfies the architectural and operational requirements. Incorrect options (Defining the scaling strategy, Defining the required Conda environments) do not provide this exact capability.
Key Takeaway: Remember ''Executing the inference logic code'' as the standard exam pattern for this topic.', 'This file contains the function definitions that are necessary to load your model to memory and make predictions. The two functions are called load_model() and predict(). The function parameters are not customizable. For example, you can define data transformations in predict() before calling the inference method of your estimator object. In other words, it is used for executing the inference logic code.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('82981caa-3b32-54a5-a410-b69bcec9ac7c', '1ca38105-d2e8-53d2-9f45-1c1db4957b1f', 'mcq'::public.question_type, 'mcq', 'Which stage in the machine learning life cycle helps identify imbalances present in data?', '["Data Monitoring", "Data Access", "Data Exploration", "Data Modeling"]'::jsonb, '[2]'::jsonb, 'Technical Rationale: The correct answer is ''Data Exploration''. In this scenario, ''Data Exploration'' satisfies the architectural and operational requirements. Incorrect options (Data Monitoring, Data Access) do not provide this exact capability.
Key Takeaway: Remember ''Data Exploration'' as the standard exam pattern for this topic.', 'The process of building and breaking the ML model has six steps. Of these, Data Exploration is used to cleanse the data by identifying corrupt, inaccurate, and incomplete data and replacing or deleting it. This also helps in identifying the imbalances present in the data.'::public.difficulty_level, medium, 1);
INSERT INTO public.subtopics (id, course_id, name, order_index) VALUES ('86aba96d-4cff-598d-843b-661b8ecde5f0', '73e8a5d1-0dd3-55fa-b9d7-b171ef5e7428', 'Machine Learning Life Cycle & Notebooks', 3);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('7c42c24a-1994-5751-96b4-c14d5c618edc', '86aba96d-4cff-598d-843b-661b8ecde5f0', 'mcq'::public.question_type, 'mcq', 'As a data scientist, you require a pipeline to train ML models. When can a pipeline run be initiated?', '["After the Active state", "Before the Active state", "During the pipeline run state", "After it is created"]'::jsonb, '[0]'::jsonb, 'In OCI Data Science Professional, After the Active state represents the standard architecture pattern for managing scalable MLOps lifecycle from experimentation to production deployment.
Key Takeaway: OCI Data Science streamlines collaborative ML pipelines using managed compute and Object Storage.', 'A pipeline life cycle has four states: Create, Active, Run, and Delete. The pipeline run state gets initiated after the active state.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('d04ec430-4dbc-5c72-9f57-3e6bb91ce17b', '86aba96d-4cff-598d-843b-661b8ecde5f0', 'mcq'::public.question_type, 'mcq', 'In the OCI Console, as part of Monitoring, of what is triggering a Pager Duty notification an example?', '["Rule", "Action", "Function", "Event"]'::jsonb, '[1]'::jsonb, 'Technical Rationale: The correct answer is ''Action''. In this scenario, ''Action'' satisfies the architectural and operational requirements. Incorrect options (Rule, Function) do not provide this exact capability.
Key Takeaway: Remember ''Action'' as the standard exam pattern for this topic.', 'Action is a user-defined response to an event, such as triggering a notification. Triggering a Pager Duty notification in this case is an example of Action.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('272c70b0-65c8-59ba-bb8f-b91b3057c197', '86aba96d-4cff-598d-843b-661b8ecde5f0', 'mcq'::public.question_type, 'mcq', 'Which statement is true about logs for Oracle Cloud Infrastructure Jobs?', '["Integrating Data Science Jobs resources with Logging is mandatory.", "Each job run sends outputs to a single log for that job.", "Logs are automatically deleted when the job and job run are deleted.", "All stdout and stderr are automatically stored when automatic log creation is enabled."]'::jsonb, '[3]'::jsonb, 'Technical Rationale: The correct answer is ''All stdout and stderr are automatically stored when automatic log creation is enabled.''. In this scenario, ''All stdout and stderr are automatically stored when automatic log creation is enabled.'' satisfies the architectural and operational requirements. Incorrect options (Integrating Data Science Jobs resources with Logging is mandatory., Each job run sends outputs to a single log for that job.) do not provide this exact capability.
Key Takeaway: Remember ''All stdout and stderr are automatically stored when automatic log creation is enabled.'' as the standard exam pattern for this topic.', 'When working with custom logs, the customer captures log events collected in a particular context. Here the standard output (stdout) and standard error (stderr) outputs from job artifacts are automatically captured.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('b6b4a28d-e539-5cf3-a24a-9cb6811f763b', '86aba96d-4cff-598d-843b-661b8ecde5f0', 'mcq'::public.question_type, 'mcq', 'Which step is unique to MLOps, as opposed to DevOps?', '["Continuous Deployment", "Continuous Training", "Continuous Delivery", "Continuous Integration"]'::jsonb, '[1]'::jsonb, 'Technical Rationale: The correct answer is ''Continuous Training''. In this scenario, ''Continuous Training'' satisfies the architectural and operational requirements. Incorrect options (Continuous Deployment, Continuous Delivery) do not provide this exact capability.
Key Takeaway: Remember ''Continuous Training'' as the standard exam pattern for this topic.', 'Continuous Training is unique to MLOps and refers to the automatic retraining of ML models for redeployment.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('12ba107e-0d89-583e-a62f-e880fddfcb82', '86aba96d-4cff-598d-843b-661b8ecde5f0', 'mcq'::public.question_type, 'mcq', 'Which statement is true about Oracle Cloud Infrastructure Data Science Jobs?', '["Jobs provisions the infrastructure to run a process on demand.", "You must use a single Shell/Bash or Python artifact to run a job.", "You must create and manage your own Jobs infrastructure.", "Jobs comes with a set of standard tasks that cannot be customized."]'::jsonb, '[0]'::jsonb, 'Technical Rationale: The correct answer is ''Jobs provisions the infrastructure to run a process on demand.''. In this scenario, ''Jobs provisions the infrastructure to run a process on demand.'' satisfies the architectural and operational requirements. Incorrect options (You must use a single Shell/Bash or Python artifact to run a job., You must create and manage your own Jobs infrastructure.) do not provide this exact capability.
Key Takeaway: Remember ''Jobs provisions the infrastructure to run a process on demand.'' as the standard exam pattern for this topic.', 'A job is a template that describes the task. In each job run, you can override some of the job configuration, and most importantly, the environment variables and CLI arguments. You can have the same job with several sequentially or simultaneously started job runs with different parameters.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('fe94e45e-c1f6-5e76-9dd7-9ea010fac1a1', '86aba96d-4cff-598d-843b-661b8ecde5f0', 'mcq'::public.question_type, 'mcq', 'Which statement us true about machine learning models?', '["A high-quality model will not need to be retrained as new information is received.", "Model performance degrades over time due to changes in data.", "Static predictions become increasingly accurate over time.", "Data models are more static and generally require fewer updates than software code."]'::jsonb, '[1]'::jsonb, 'Technical Rationale: The correct answer is ''Model performance degrades over time due to changes in data.''. In this scenario, ''Model performance degrades over time due to changes in data.'' satisfies the architectural and operational requirements. Incorrect options (A high-quality model will not need to be retrained as new information is received., Static predictions become increasingly accurate over time.) do not provide this exact capability.
Key Takeaway: Remember ''Model performance degrades over time due to changes in data.'' as the standard exam pattern for this topic.', 'Machine learning models are data driven. Whenever the data changes, the model needs retraining. Else the performance degrades over time.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('78b0230f-1979-5995-a2b5-4f599685a365', '86aba96d-4cff-598d-843b-661b8ecde5f0', 'mcq'::public.question_type, 'mcq', 'You want to change the autoscaling configuration for infrastructure and non-infrastructure fields for an existing model deployment in an Active state in Oracle Data Science. Which statement is true?', '["You can modify the Autoscaling Scaling Policy fields and other configurations simultaneously regardless of its state.", "You must disable the model deployment to update the Autoscaling Scaling Policy fields and other configurations.", "Infrastructure-related aspects can''t be modified for a model deployment, regardless of state.", "Non-infrastructure-related aspects can''t be modified for an active model deployment."]'::jsonb, '[1]'::jsonb, 'OCI Model Deployment provides fully managed, scalable HTTPS endpoints for real-time model inference, integrated with OCI Load Balancing, Logging, and IAM authentication.
Correct answer: You must disable the model deployment to update the Autoscaling Scaling Policy fields and other configurations..
Key Takeaway: Model Deployments scale inference workloads horizontally behind a managed HTTPS endpoint.', 'You can enable autoscaling for an existing model deployment or update any existing autoscaling configuration. For model deployments in an Active state, note that modifications to the Autoscaling Scaling Policy fields must occur independently, without simultaneous changes to other configurations. However, updates to fields such as Display Name, Description, Tags, and other non-infrastructure-related aspects are allowed. In contrast, when the model deployment is Inactive, you have the flexibility to change all options simultaneously.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('030c3c71-9bbb-5943-9304-c29c45b8e0a3', '86aba96d-4cff-598d-843b-661b8ecde5f0', 'mcq'::public.question_type, 'mcq', 'Why would you use a mini batch when processing a job in Data Science Jobs?', '["You want to process data frequently.", "There is a small amount of total data to process.", "You want several distributed models to run simultaneously.", "You do not need to process data quickly."]'::jsonb, '[0]'::jsonb, 'Technical Rationale: The correct answer is ''You want to process data frequently.''. In this scenario, ''You want to process data frequently.'' satisfies the architectural and operational requirements. Incorrect options (There is a small amount of total data to process., You want several distributed models to run simultaneously.) do not provide this exact capability.
Key Takeaway: Remember ''You want to process data frequently.'' as the standard exam pattern for this topic.', 'Sometimes so much data comes in or needs to be processed so quickly that a mini batch is preferable. This is a set of more frequent job runs that processes a smaller amount of data at a time. A good example of when to use a mini batch is a bank analyzing transactions to search for fraud. Every several minutes, a job is run that takes data from Object Storage and looks for fraudulent transactions.'::public.difficulty_level, medium, 1);
INSERT INTO public.subtopics (id, course_id, name, order_index) VALUES ('07297907-46f1-579c-b3a0-b2ce35be3c6c', '73e8a5d1-0dd3-55fa-b9d7-b171ef5e7428', 'MLOps Practices & Pipeline Execution', 4);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('a91cebd6-563b-5f46-886f-9c6f0737a269', '07297907-46f1-579c-b3a0-b2ce35be3c6c', 'mcq'::public.question_type, 'mcq', 'Which option indicates the three types of data used for Data Labeling?', '["Text, audio, video", "Image, text, document", "Graphic, text, document", "Image, audio, document"]'::jsonb, '[1]'::jsonb, 'Technical Rationale: The correct answer is ''Image, text, document''. In this scenario, ''Image, text, document'' satisfies the architectural and operational requirements. Incorrect options (Text, audio, video, Graphic, text, document) do not provide this exact capability.
Key Takeaway: Remember ''Image, text, document'' as the standard exam pattern for this topic.', 'Data Labeling is the process of identifying properties (labels) of documents, text, and images (records), and annotating (labeling) them with those properties.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('198b4f55-a45a-5629-86ff-b27a03211085', '07297907-46f1-579c-b3a0-b2ce35be3c6c', 'mcq'::public.question_type, 'mcq', 'What is the name of the machine learning library used in Apache Spark?', '["Structured Streaming", "GraphX", "MLlib", "HadoopML"]'::jsonb, '[2]'::jsonb, 'Technical Rationale: The correct answer is ''MLlib''. In this scenario, ''MLlib'' satisfies the architectural and operational requirements. Incorrect options (Structured Streaming, GraphX) do not provide this exact capability.
Key Takeaway: Remember ''MLlib'' as the standard exam pattern for this topic.', 'PySpark 3.2 and the Big Data service leverage the power of Apache Spark and MLlib to speed up model building.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('1409cd78-454f-5e00-869d-eae597e46b9c', '07297907-46f1-579c-b3a0-b2ce35be3c6c', 'mcq'::public.question_type, 'mcq', 'You are a researcher who requires access to large data sets. Which OCI service would you use?', '["Oracle Open Data", "OCI Data Science", "Oracle Databases", "ADW"]'::jsonb, '[0]'::jsonb, 'Technical Rationale: The correct answer is ''Oracle Open Data''. In this scenario, ''Oracle Open Data'' satisfies the architectural and operational requirements. Incorrect options (OCI Data Science, Oracle Databases) do not provide this exact capability.
Key Takeaway: Remember ''Oracle Open Data'' as the standard exam pattern for this topic.', 'Oracle Open Data is a service from Oracle for Research that makes large data sets available to researchers around the world. It curates information like spatial images, protein sequences, and annotated text files from the world’s leading scientific data sources.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('00547765-c088-51b8-9317-5d273e879da3', '07297907-46f1-579c-b3a0-b2ce35be3c6c', 'mcq'::public.question_type, 'mcq', 'Which OCI service provides a scalable environment for developers and data scientists to run Apache Spark applications at scale?', '["Data Science", "Data Labeling", "Anomaly Detection", "Data Flow"]'::jsonb, '[3]'::jsonb, 'Technical Rationale: The correct answer is ''Data Flow''. In this scenario, ''Data Flow'' satisfies the architectural and operational requirements. Incorrect options (Data Science, Data Labeling) do not provide this exact capability.
Key Takeaway: Remember ''Data Flow'' as the standard exam pattern for this topic.', 'Oracle Cloud Infrastructure Data Flow is a fully managed service for running Apache Spark applications. It allows developers to focus on their applications and provides an easy runtime environment to execute them. It has a simple user interface with API support for integration with applications and workflows.'::public.difficulty_level, medium, 1);
INSERT INTO public.subtopics (id, course_id, name, order_index) VALUES ('74aef361-5ad9-50c5-b068-1a0fd76e6fc6', '73e8a5d1-0dd3-55fa-b9d7-b171ef5e7428', 'Related OCI Services & Security', 5);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('f190a6a8-daf1-5154-b2ef-ce79eae81e5b', '74aef361-5ad9-50c5-b068-1a0fd76e6fc6', 'mcq'::public.question_type, 'mcq', 'Which statement about dynamic groups is true?', '["<p>They are a logical grouping of resources that can be accessed only by certain groups that have received administrator permission.</p>", "<p>They define a set of matching rules that determine group membership instead of requiring members to be added explicitly.</p>", "<p>They are individual users that are grouped in OCI by administrators and granted access to Data Science resources within compartments.</p>", "<p>They define what Data Science principals, such as users and resources, have access to in OCI.</p>"]'::jsonb, '[1]'::jsonb, 'Technical Rationale: The correct answer is ''<p>They define a set of matching rules that determine group membership instead of requiring members to be added explicitly.</p>''. In this scenario, ''<p>They define a set of matching rules that determine group membership instead of requiring members to be added explicitly.</p>'' satisfies the architectural and operational requirements. Incorrect options (<p>They are a logical grouping of resources that can be accessed only by certain groups that have received administrator permission.</p>, <p>They are individual users that are grouped in OCI by administrators and granted access to Data Science resources within compartments.</p>) do not provide this exact capability.
Key Takeaway: Remember ''<p>They define a set of matching rules that determine group membership instead of requiring members to be added explicitly.</p>'' as the standard exam pattern for this topic.', 'When you create a dynamic group, you define a set of matching rules to define the group members.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('175b1d42-50d9-570b-95f1-984ac3175ee9', '74aef361-5ad9-50c5-b068-1a0fd76e6fc6', 'mcq'::public.question_type, 'mcq', 'Which OCI Data Science interaction method can function in both ways — with or without the need of scripting?', '["Language SDKs", "CLI", "REST API", "OCI Console"]'::jsonb, '[3]'::jsonb, 'Technical Rationale: The correct answer is ''OCI Console''. In this scenario, ''OCI Console'' satisfies the architectural and operational requirements. Incorrect options (Language SDKs, CLI) do not provide this exact capability.
Key Takeaway: Remember ''OCI Console'' as the standard exam pattern for this topic.', 'The OCI Console offers interaction with the Data Science service without the need for scripts.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('9bc73536-4e0c-5c28-b11a-177e2de476ec', '74aef361-5ad9-50c5-b068-1a0fd76e6fc6', 'mcq'::public.question_type, 'mcq', 'What is feature engineering in machine learning used for?', '["<p>To interpret ML models</p>", "<p>To perform parameter tuning</p>", "<p>To represent the data in a way that helps the model learn more effectively</p>", "<p>To help understand the data set features</p>"]'::jsonb, '[2]'::jsonb, 'Technical Rationale: The correct answer is ''<p>To represent the data in a way that helps the model learn more effectively</p>''. In this scenario, ''<p>To represent the data in a way that helps the model learn more effectively</p>'' satisfies the architectural and operational requirements. Incorrect options (<p>To interpret ML models</p>, <p>To perform parameter tuning</p>) do not provide this exact capability.
Key Takeaway: Remember ''<p>To represent the data in a way that helps the model learn more effectively</p>'' as the standard exam pattern for this topic.', 'Feature engineering is used to represent the data in a way that helps the model learn more effectively.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('ba7b4695-5d83-5090-b2ec-fe8f33660aa7', '74aef361-5ad9-50c5-b068-1a0fd76e6fc6', 'mcq'::public.question_type, 'mcq', 'What does the Data Science Service template in Oracle Resource Manager (ORM) NOT automatically create?', '["Required user groups", "Individual Data Science users", "Dynamic groups", "Policies for a basic use case"]'::jsonb, '[1]'::jsonb, 'Technical Rationale: The correct answer is ''Individual Data Science users''. In this scenario, ''Individual Data Science users'' satisfies the architectural and operational requirements. Incorrect options (Required user groups, Dynamic groups) do not provide this exact capability.
Key Takeaway: Remember ''Individual Data Science users'' as the standard exam pattern for this topic.', 'Oracle Resource Manager (ORM) automatically creates the policies for a basic use case, required user groups, and dynamic groups. It doesn’t create individual Data Science users.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('8df01644-c6cc-5a11-a73a-b9198e89012e', '74aef361-5ad9-50c5-b068-1a0fd76e6fc6', 'mcq'::public.question_type, 'mcq', 'Which statement about resource principals is true?', '["The Data Science service does not provide authentication via a notebook session''s or job run\u2019s resource principal to access other OCI resources.", "A resource principal is a feature of IAM that enables resources to be authorized principal actors.", "A resource principal is not a  secure way to authenticate to resources, compared to the OCI configuration and API key approach.", "When you authenticate using a resource principal, you need to create and manage credentials to access OCI resources."]'::jsonb, '[1]'::jsonb, 'Technical Rationale: The correct answer is ''A resource principal is a feature of IAM that enables resources to be authorized principal actors.''. In this scenario, ''A resource principal is a feature of IAM that enables resources to be authorized principal actors.'' satisfies the architectural and operational requirements. Incorrect options (The Data Science service does not provide authentication via a notebook session''s or job run’s resource principal to access other OCI resources., A resource principal is not a  secure way to authenticate to resources, compared to the OCI configuration and API key approach.) do not provide this exact capability.
Key Takeaway: Remember ''A resource principal is a feature of IAM that enables resources to be authorized principal actors.'' as the standard exam pattern for this topic.', 'A resource principal can be used to authenticate and access Oracle Cloud Infrastructure (OCI) resources. The resource principal consists of a temporary session token and secure credentials that enable the database to authenticate itself to other OCI services. To use the resource principal, you or your tenancy administrator define the OCI policies and a dynamic group that allows you to access OCI resources with a resource principal.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('2e9dd22c-d0fb-59d8-82bd-e5f672abcb85', '74aef361-5ad9-50c5-b068-1a0fd76e6fc6', 'mcq'::public.question_type, 'mcq', 'Which allows the sharing and loading back of ML models into a Notebook session?', '["Model deployment", "Model taxonomy", "Model catalog", "Model provenance"]'::jsonb, '[2]'::jsonb, 'In OCI Data Science Professional, Model catalog represents the standard architecture pattern for managing scalable MLOps lifecycle from experimentation to production deployment.
Key Takeaway: OCI Data Science streamlines collaborative ML pipelines using managed compute and Object Storage.', 'The model catalog is a centralized and managed repository of model artifacts. A stored model includes metadata about the provenance of the model including Git-related information and the script or notebook used to push the model to the catalog. Models stored in the model catalog can be shared across members of a team and they can be loaded back into a Notebook session.'::public.difficulty_level, medium, 1);
INSERT INTO public.questions (id, subtopic_id, type, question_type, question_text, options, correct_answers, explanation, difficulty, correct_option_count, total_options)
VALUES ('1898e30d-0544-5654-b6b7-375a914643e7', '74aef361-5ad9-50c5-b068-1a0fd76e6fc6', 'mcq'::public.question_type, 'mcq', 'Which feature of Oracle Cloud Infrastructure Data Science provides an interactive coding environment for building and training machine learning models?', '["Projects", "Jobs", "Model catalog", "Notebook session"]'::jsonb, '[3]'::jsonb, 'Technical Rationale: The correct answer is ''Notebook session''. In this scenario, ''Notebook session'' satisfies the architectural and operational requirements. Incorrect options (Projects, Jobs) do not provide this exact capability.
Key Takeaway: Remember ''Notebook session'' as the standard exam pattern for this topic.', 'OCI Notebook sessions are interactive coding environments for building and training models. A Notebook session is created inside a Data Science project.'::public.difficulty_level, medium, 1);
